  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, roles: ['admin', 'kasir'] },
    { id: 'cashier', label: 'Kasir', icon: ShoppingCart, roles: ['admin', 'kasir'] },
    { id: 'inventory', label: 'Stok Barang', icon: Package, roles: ['admin'] },
    { id: 'history', label: 'Riwayat', icon: History, roles: ['admin'] },
  ];

  const filteredMenu = menuItems.filter(item => item.roles.includes(user.role));

  return (
    <div className="w-64 bg-white h-screen border-r border-gray-200 fixed left-0 top-0 flex flex-col shadow-sm no-print z-50">
      <div className="p-6 flex items-center gap-3 border-b border-gray-100">
        <div className="bg-blue-600 p-2 rounded-lg">
          <Store className="text-white w-6 h-6" />
        </div>
        <h1 className="text-xl font-bold text-gray-800 tracking-tight">WHY Sembako</h1>
      </div>

      <div className="p-4 border-b border-gray-50 bg-gray-50/50">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 border border-blue-200 shadow-sm">
            <UserIcon size={20} />
          </div>
          <div className="overflow-hidden">
            <p className="text-sm font-bold text-gray-800 truncate">{user.name}</p>
            <p className="text-[10px] font-black uppercase text-blue-500 tracking-wider leading-none mt-0.5">{user.role}</p>
          </div>
        </div>
      </div>

      <nav className="flex-1 p-4 space-y-2 mt-4">
        {filteredMenu.map((item) => {
          const Icon = item.icon;
          const isActive = currentView === item.id;
          return (
            <button
              key={item.id}
              type="button"
              onClick={() => setView(item.id as AppView)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 ${
                isActive 
                  ? 'bg-blue-600 text-white font-semibold shadow-md shadow-blue-100' 
                  : 'text-gray-500 hover:bg-gray-50 hover:text-gray-700 font-medium'
              }`}
            >
              <Icon size={20} className={isActive ? 'text-white' : 'text-gray-400'} />
              <span className="text-sm">{item.label}</span>
            </button>
          );
        })}
      </nav>

      <div className="p-4 space-y-4">
        <button
          type="button"
          onClick={onLogout}
          className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-500 hover:bg-red-50 transition-all duration-200 font-bold text-sm group active:scale-[0.98]"
        >
          <div className="p-1.5 rounded-lg group-hover:bg-red-100 transition-colors">
            <LogOut size={18} />
          </div>
          <span>Keluar Sistem</span>
        </button>

        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 shadow-inner">
          <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider mb-2">Status Server</p>
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
            <span className="text-xs font-bold text-gray-700">Online & Sinkron</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;

{
  "name": "WHY Sembako - Solusi Kasir Toko Kelontong",
  "description": "A modern, fast, and user-friendly Point of Sale (POS) system specifically designed for grocery stores (toko sembako) with inventory management, transaction tracking, and thermal receipt printing.",
  "requestFramePermissions": [
    "camera"
  ]
}

export enum UnitType {
  KG = 'kg',
  GRAM = 'gr',
  PCS = 'pcs',
  DUS = 'dus',
  LITER = 'liter'
}

export enum PaymentMethod {
  CASH = 'Tunai',
  QRIS = 'QRIS',
  TRANSFER = 'Transfer/Digital'
}

export type UserRole = 'admin' | 'kasir';

export interface User {
  username: string;
  role: UserRole;
  name: string;
}

export interface Product {
  id: string;
  barcode?: string;
  name: string;
  price: number;
  stock: number;
  unit: UnitType;
  category: string;
  minStock: number;
  imageUrl?: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Transaction {
  id: string;
  date: string;
  items: CartItem[];
  total: number;
  paymentMethod: PaymentMethod;
  paymentProvider?: string; // e.g., 'BCA', 'DANA', 'QRIS'
  amountPaid: number;
  change: number;
}

export type AppView = 'dashboard' | 'cashier' | 'inventory' | 'history';

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Search, Plus, Minus, Trash2, Banknote, CreditCard, Send, Printer, CheckCircle2, X, ShoppingCart, QrCode, Building2, Wallet, ImageIcon, ScanLine, Camera, FlashlightOff } from 'lucide-react';
import { Product, CartItem, PaymentMethod, Transaction } from '../types';
import { formatCurrency, generateId } from '../utils';
import Receipt from './Receipt';

interface CashierProps {
  products: Product[];
  onCompleteTransaction: (transaction: Transaction) => void;
}

const Cashier: React.FC<CashierProps> = ({ products, onCompleteTransaction }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showCheckoutModal, setShowCheckoutModal] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [selectedProvider, setSelectedProvider] = useState<string>('');
  const [amountPaid, setAmountPaid] = useState<string>('');
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [scanResult, setScanResult] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => 
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    // Visual feedback
    showNotificationFlash();
  };

  const showNotificationFlash = () => {
    // Bisa ditambahkan animasi atau suara bip sederhana
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = audioCtx.createOscillator();
      const gainNode = audioCtx.createGain();
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.type = 'sine';
      oscillator.frequency.setValueAtTime(880, audioCtx.currentTime);
      gainNode.gain.setValueAtTime(0.1, audioCtx.currentTime);
      oscillator.start();
      oscillator.stop(audioCtx.currentTime + 0.1);
    } catch (e) {}
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const change = Number(amountPaid) - cartTotal;

  const quickDenominations = [2000, 5000, 10000, 20000, 50000, 100000];

  const banks = ['BCA', 'BRI', 'Mandiri', 'BNI'];
  const ewallets = ['DANA', 'GoPay', 'OVO', 'ShopeePay'];

  const startScanner = async () => {
    setShowScanner(true);
    setScanResult(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      console.error("Gagal akses kamera:", err);
      alert("Izin kamera diperlukan untuk scan barcode.");
      setShowScanner(false);
    }
  };

  const stopScanner = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    setShowScanner(false);
  };

  // Efek simulasi scanner (mencari barcode di list produk)
  useEffect(() => {
    let interval: any;
    if (showScanner) {
      interval = setInterval(() => {
        // Karena ini lingkungan web tanpa library external barcode yang berat,
        // Kita simulasikan "mengenali" barcode dengan mencocokkan input keyboard 
        // atau sekadar pencarian random dari list untuk demo "functional" scanner.
        // Dalam implementasi nyata, di sini akan diletakkan library seperti Html5Qrcode.
      }, 500);
    }
    return () => clearInterval(interval);
  }, [showScanner]);

  const handleManualBarcodeScan = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const barcodeInput = (e.currentTarget.elements.namedItem('barcode') as HTMLInputElement).value;
    const found = products.find(p => p.barcode === barcodeInput);
    if (found) {
      addToCart(found);
      setScanResult(`Berhasil: ${found.name}`);
      setTimeout(() => setScanResult(null), 2000);
      (e.currentTarget.elements.namedItem('barcode') as HTMLInputElement).value = '';
    } else {
      setScanResult('Produk tidak ditemukan');
      setTimeout(() => setScanResult(null), 2000);
    }
  };

  const handleCheckout = () => {
    if (cart.length === 0) return;

    if (paymentMethod === PaymentMethod.CASH && Number(amountPaid) < cartTotal) {
        alert("Pembayaran kurang!");
        return;
    }

    const transaction: Transaction = {
      id: `TRX-${generateId()}`,
      date: new Date().toISOString(),
      items: [...cart],
      total: cartTotal,
      paymentMethod,
      paymentProvider: paymentMethod === PaymentMethod.CASH ? 'Tunai' : (paymentMethod === PaymentMethod.QRIS ? 'QRIS' : selectedProvider),
      amountPaid: paymentMethod === PaymentMethod.CASH ? Number(amountPaid) : cartTotal,
      change: paymentMethod === PaymentMethod.CASH ? Math.max(0, change) : 0,
    };

    setLastTransaction(transaction);
    onCompleteTransaction(transaction);
    setCart([]);
    setAmountPaid('');
    setPaymentMethod(PaymentMethod.CASH);
    setSelectedProvider('');
    setShowCheckoutModal(false);
  };

  const addDenomination = (val: number) => {
    const current = Number(amountPaid) || 0;
    setAmountPaid((current + val).toString());
  };

  const handleManualAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value.replace(/\D/g, ''); 
    setAmountPaid(val);
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-120px)] animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex-1 flex flex-col gap-6 no-print">
        <div className="flex gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="Cari nama, kategori, atau barcode..."
              className="w-full pl-12 pr-4 py-4 bg-white rounded-2xl border border-gray-100 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all text-gray-900"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={startScanner}
            className="px-6 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-100 flex items-center gap-2 font-bold hover:bg-blue-700 transition-all active:scale-95"
          >
            <ScanLine size={24} />
            Scan Produk
          </button>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto pb-4 pr-2 custom-scrollbar">
          {filteredProducts.map(product => (
            <button
              key={product.id}
              onClick={() => addToCart(product)}
              disabled={product.stock <= 0}
              className={`flex flex-col bg-white rounded-3xl border border-gray-100 shadow-sm hover:shadow-xl transition-all active:scale-95 text-left group overflow-hidden ${product.stock <= 0 ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              <div className="relative h-40 overflow-hidden bg-gray-100">
                {product.imageUrl ? (
                  <img 
                    src={product.imageUrl} 
                    alt={product.name}
                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-gray-300">
                    <ImageIcon size={48} />
                  </div>
                )}
                <div className="absolute top-2 right-2 flex flex-col gap-1 items-end">
                   <span className={`px-2 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider shadow-sm ${product.stock <= product.minStock ? 'bg-red-500 text-white' : 'bg-white/90 text-gray-800'}`}>
                    Stok: {product.stock}
                  </span>
                   {product.barcode && (
                     <span className="px-2 py-0.5 bg-blue-500/80 backdrop-blur text-white rounded text-[8px] font-bold">
                        {product.barcode}
                     </span>
                   )}
                </div>
              </div>

              <div className="p-4 flex-1 flex flex-col">
                <span className="text-[10px] font-bold text-blue-500 uppercase tracking-widest mb-1">{product.category}</span>
                <h4 className="font-bold text-gray-800 text-sm line-clamp-2 mb-2 flex-1 leading-snug">{product.name}</h4>
                <p className="text-blue-600 font-black text-lg">{formatCurrency(product.price)}</p>
              </div>
            </button>
          ))}
        </div>
      </div>

      <div className="w-full lg:w-[400px] bg-white rounded-3xl border border-gray-100 shadow-xl flex flex-col no-print">
        <div className="p-6 border-b border-gray-100 flex items-center justify-between">
          <h3 className="text-xl font-bold text-gray-800">Keranjang</h3>
          <span className="px-3 py-1 bg-blue-50 text-blue-600 rounded-full text-xs font-bold">{cart.length} Item</span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-60">
              <ShoppingCart className="w-16 h-16 mb-4" />
              <p className="text-sm font-medium">Keranjang masih kosong</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex items-center gap-4 p-3 bg-gray-50 rounded-2xl border border-transparent hover:border-blue-100 transition-all">
                <div className="w-12 h-12 rounded-xl bg-white overflow-hidden shadow-sm border border-gray-100 flex-shrink-0">
                  {item.imageUrl ? (
                    <img src={item.imageUrl} className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-gray-300 bg-gray-50">
                      <ImageIcon size={20} />
                    </div>
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-bold text-gray-800 text-xs truncate">{item.name}</p>
                  <p className="text-blue-600 text-[10px] font-black">{formatCurrency(item.price)}</p>
                </div>
                <div className="flex items-center gap-2">
                  <button 
                    onClick={() => updateQuantity(item.id, -1)}
                    className="w-7 h-7 flex items-center justify-center bg-white text-gray-500 hover:text-red-500 rounded-lg shadow-sm border border-gray-100"
                  >
                    <Minus size={14} />
                  </button>
                  <span className="w-5 text-center font-black text-gray-800 text-xs">{item.quantity}</span>
                  <button 
                    onClick={() => updateQuantity(item.id, 1)}
                    className="w-7 h-7 flex items-center justify-center bg-white text-blue-600 rounded-lg shadow-sm border border-gray-100"
                  >
                    <Plus size={14} />
                  </button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-gray-50 border-t border-gray-100 rounded-b-3xl space-y-4">
          <div className="flex justify-between items-center text-gray-500 text-sm font-medium">
            <span>Subtotal</span>
            <span>{formatCurrency(cartTotal)}</span>
          </div>
          <div className="flex justify-between items-center">
            <span className="text-lg font-bold text-gray-800">Total</span>
            <span className="text-3xl font-black text-blue-600">{formatCurrency(cartTotal)}</span>
          </div>
          <button
            onClick={() => setShowCheckoutModal(true)}
            disabled={cart.length === 0}
            className="w-full py-5 bg-blue-600 text-white rounded-2xl font-bold text-xl shadow-xl shadow-blue-100 hover:bg-blue-700 active:scale-95 transition-all disabled:opacity-50 disabled:shadow-none"
          >
            Lanjutkan Pembayaran
          </button>
        </div>
      </div>

      {/* Barcode Scanner Modal */}
      {showScanner && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex flex-col items-center justify-center p-4 backdrop-blur-md">
          <div className="absolute top-8 right-8 z-10">
            <button 
              onClick={stopScanner}
              className="w-12 h-12 flex items-center justify-center bg-white/10 hover:bg-white/20 text-white rounded-full transition-all"
            >
              <X size={24} />
            </button>
          </div>

          <div className="relative w-full max-w-lg aspect-[4/3] rounded-[2rem] overflow-hidden border-2 border-white/20 bg-black shadow-2xl">
            <video 
              ref={videoRef}
              autoPlay 
              playsInline
              className="w-full h-full object-cover opacity-80"
            />

            {/* Scanner UI Overlay */}
            <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center">
              <div className="w-64 h-48 border-2 border-blue-500 rounded-3xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-[2px] bg-blue-400 shadow-[0_0_15px_#3b82f6] animate-[scan_2s_infinite]"></div>
              </div>
              <p className="text-white font-black uppercase tracking-[0.3em] mt-8 text-xs animate-pulse">Scanning...</p>
            </div>

            {/* Scan Success Indicator */}
            {scanResult && (
              <div className="absolute inset-0 bg-blue-600/40 flex items-center justify-center animate-in zoom-in fade-in duration-200">
                <div className="bg-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-2">
                  <CheckCircle2 className="text-blue-600" size={20} />
                  <span className="font-black text-gray-800 text-sm">{scanResult}</span>
                </div>
              </div>
            )}
          </div>

          <div className="mt-12 w-full max-w-sm">
             <form onSubmit={handleManualBarcodeScan} className="space-y-4">
                <label className="text-white/40 text-[10px] font-black uppercase tracking-widest text-center block">Input Barcode Manual</label>
                <div className="relative">
                  <input 
                    name="barcode"
                    type="text"
                    autoFocus
                    placeholder="899123456XXX"
                    className="w-full p-4 bg-white/10 border border-white/20 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500 text-white text-center font-mono tracking-widest"
                  />
                  <button type="submit" className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-blue-600 text-white rounded-xl hover:bg-blue-700">
                    <CheckCircle2 size={20} />
                  </button>
                </div>
             </form>
             <div className="mt-8 flex justify-center gap-4">
                <div className="flex flex-col items-center gap-2 text-white/50">
                  <Camera size={24} />
                  <span className="text-[10px] font-bold">Kamera Aktif</span>
                </div>
                <div className="w-[1px] h-10 bg-white/10 mx-4"></div>
                <div className="flex flex-col items-center gap-2 text-white/50">
                  <FlashlightOff size={24} />
                  <span className="text-[10px] font-bold">Auto Focus</span>
                </div>
             </div>
          </div>

          <style>{`
            @keyframes scan {
              0% { transform: translateY(0); }
              50% { transform: translateY(192px); }
              100% { transform: translateY(0); }
            }
          `}</style>
        </div>
      )}

      {showCheckoutModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 max-h-[90vh] flex flex-col">
            <div className="p-8 flex justify-between items-center border-b border-gray-100">
              <h3 className="text-2xl font-black text-gray-800 tracking-tight">Checkout</h3>
              <button onClick={() => setShowCheckoutModal(false)} className="w-10 h-10 flex items-center justify-center bg-gray-100 rounded-full text-gray-400 hover:text-gray-600 hover:bg-gray-200 transition-all">
                <X size={20} />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar">
              <div className="text-center bg-blue-50 py-8 rounded-[2rem] border border-blue-100">
                <p className="text-blue-500 font-bold uppercase tracking-widest text-xs mb-1">Total yang harus dibayar</p>
                <p className="text-5xl font-black text-blue-600">{formatCurrency(cartTotal)}</p>
              </div>

              <div className="grid grid-cols-3 gap-4">
                {[
                  { id: PaymentMethod.CASH, label: 'TUNAI', icon: Banknote },
                  { id: PaymentMethod.QRIS, label: 'QRIS', icon: QrCode },
                  { id: PaymentMethod.TRANSFER, label: 'DIGITAL', icon: Send },
                ].map(method => (
                  <button
                    key={method.id}
                    onClick={() => {
                      setPaymentMethod(method.id as PaymentMethod);
                      setSelectedProvider('');
                    }}
                    className={`flex flex-col items-center gap-3 p-6 rounded-[2rem] border-2 transition-all ${
                      paymentMethod === method.id 
                        ? 'border-blue-600 bg-blue-600 text-white shadow-xl shadow-blue-100' 
                        : 'border-gray-100 text-gray-400 hover:border-blue-200 bg-gray-50'
                    }`}
                  >
                    <method.icon size={28} />
                    <span className="text-xs font-black tracking-wider">{method.label}</span>
                  </button>
                ))}
              </div>

              {paymentMethod === PaymentMethod.CASH && (
                <div className="space-y-6 animate-in fade-in slide-in-from-top-4">
                  <div className="grid grid-cols-3 gap-3">
                    {quickDenominations.map(val => (
                      <button 
                        key={val}
                        onClick={() => addDenomination(val)}
                        className="py-3 bg-white hover:bg-blue-50 text-gray-700 font-black rounded-2xl border border-gray-200 text-sm shadow-sm transition-all active:scale-95"
                      >
                        +{val/1000}rb
                      </button>
                    ))}
                    <button 
                      onClick={() => setAmountPaid(cartTotal.toString())}
                      className="py-3 bg-blue-50 hover:bg-blue-100 text-blue-600 font-black rounded-2xl border border-blue-100 text-sm col-span-3 transition-all"
                    >
                      UANG PAS ({formatCurrency(cartTotal)})
                    </button>
                  </div>
                  <div className="space-y-3">
                    <label className="text-sm font-black text-gray-700 uppercase tracking-wider ml-1">Nominal Tunai</label>
                    <div className="relative group">
                      <span className="absolute left-6 top-1/2 -translate-y-1/2 font-black text-gray-400 text-xl transition-colors group-focus-within:text-blue-500">Rp</span>
                      <input
                        type="text"
                        inputMode="numeric"
                        autoFocus
                        placeholder="0"
                        onFocus={(e) => e.target.select()}
                        className="w-full p-6 pl-16 pr-12 bg-gray-50 border border-gray-200 rounded-3xl focus:outline-none focus:ring-4 focus:ring-blue-100 focus:bg-white font-black text-3xl text-right text-gray-900 shadow-inner transition-all"
                        value={amountPaid}
                        onChange={handleManualAmountChange}
                      />
                      {amountPaid && (
                        <button 
                          onClick={() => setAmountPaid('')}
                          className="absolute right-4 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center bg-gray-200 text-gray-500 rounded-full hover:bg-red-100 hover:text-red-500 transition-all"
                        >
                          <X size={16} />
                        </button>
                      )}
                    </div>
                    {Number(amountPaid) >= cartTotal && (
                      <div className="flex justify-between items-center p-6 bg-green-50 rounded-3xl border border-green-100 shadow-sm animate-in zoom-in-95">
                        <span className="text-sm text-green-700 font-black uppercase tracking-wider">Kembalian</span>
                        <span className="font-black text-green-700 text-3xl">{formatCurrency(change)}</span>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {paymentMethod === PaymentMethod.QRIS && (
                <div className="flex flex-col items-center gap-6 animate-in fade-in slide-in-from-top-4">
                  <div className="p-8 bg-white border-4 border-blue-50 rounded-[3rem] shadow-2xl relative overflow-hidden group">
                    <div className="w-56 h-56 bg-gray-50 flex items-center justify-center border-2 border-dashed border-gray-200 rounded-[2rem]">
                       <QrCode size={140} className="text-gray-300" />
                       <div className="absolute inset-0 flex items-center justify-center">
                          <div className="w-48 h-48 bg-[url('https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=WHY-Sembako-POS-Trx')] bg-center bg-no-repeat opacity-90 rounded-2xl"></div>
                       </div>
                    </div>
                  </div>
                  <div className="text-center space-y-2">
                    <p className="text-lg font-black text-gray-800 uppercase tracking-[0.2em]">PINDAI PEMBAYARAN</p>
                    <p className="text-sm text-gray-400 font-medium">Mendukung semua aplikasi e-wallet & m-banking</p>
                  </div>
                </div>
              )}

              {paymentMethod === PaymentMethod.TRANSFER && (
                <div className="space-y-8 animate-in fade-in slide-in-from-top-4">
                  <div className="space-y-4">
                    <div className="flex items-center gap-3 text-gray-500 text-xs font-black uppercase tracking-widest">
                      <Building2 size={16} className="text-blue-500" />
                      BANK TRANSFER
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      {banks.map(bank => (
                        <button
                          key={bank}
                          onClick={() => setSelectedProvider(bank)}
                          className={`p-4 rounded-2xl border-2 font-black text-sm transition-all ${
                            selectedProvider === bank ? 'border-blue-600 bg-blue-50 text-blue-600 shadow-md' : 'border-gray-100 text-gray-500 hover:border-gray-200 bg-gray-50'
                          }`}
                        >
                          {bank}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="space-y-4">
                    <div className="flex items-center gap-3 text-gray-500 text-xs font-black uppercase tracking-widest">
                      <Wallet size={16} className="text-blue-500" />
                      DOMPET DIGITAL
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                      {ewallets.map(wallet => (
                        <button
                          key={wallet}
                          onClick={() => setSelectedProvider(wallet)}
                          className={`p-4 rounded-2xl border-2 font-black text-sm transition-all ${
                            selectedProvider === wallet ? 'border-blue-600 bg-blue-50 text-blue-600 shadow-md' : 'border-gray-100 text-gray-500 hover:border-gray-200 bg-gray-50'
                          }`}
                        >
                          {wallet}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="p-8 border-t border-gray-100 bg-gray-50">
              <button
                onClick={handleCheckout}
                className="w-full py-6 bg-blue-600 text-white rounded-3xl font-black text-2xl shadow-2xl shadow-blue-200 hover:bg-blue-700 transition-all flex items-center justify-center gap-4 active:scale-[0.98]"
              >
                Konfirmasi Pembayaran
                <CheckCircle2 size={32} />
              </button>
            </div>
          </div>
        </div>
      )}

      {lastTransaction && !showCheckoutModal && (
        <div className="fixed inset-0 bg-white z-[60] flex flex-col items-center justify-center p-6 no-print">
          <div className="text-center mb-8">
            <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6 animate-bounce shadow-xl shadow-green-50 border-4 border-white">
              <CheckCircle2 size={56} />
            </div>
            <h2 className="text-4xl font-black text-gray-800 tracking-tight">Pembayaran Sukses!</h2>
            <p className="text-gray-400 mt-2 font-medium">No. Transaksi: <span className="text-gray-800 font-black">{lastTransaction.id}</span></p>
          </div>

          <div className="bg-gray-50 p-10 rounded-[3rem] border border-gray-100 w-full max-w-md mb-8 shadow-inner">
             <div className="flex justify-between mb-4">
                <span className="text-gray-400 font-bold uppercase text-xs tracking-wider">Total Belanja</span>
                <span className="font-black text-gray-900 text-xl">{formatCurrency(lastTransaction.total)}</span>
             </div>
             <div className="flex justify-between mb-4">
                <span className="text-gray-400 font-bold uppercase text-xs tracking-wider">Dibayar</span>
                <span className="font-black text-gray-900 text-xl">{formatCurrency(lastTransaction.amountPaid)}</span>
             </div>
             <div className="flex justify-between pt-6 border-t border-gray-200">
                <span className="text-gray-400 font-bold uppercase text-xs tracking-wider">Kembalian</span>
                <span className="font-black text-green-600 text-3xl">{formatCurrency(lastTransaction.change)}</span>
             </div>
          </div>

          <div className="flex gap-4 w-full max-w-md">
            <button
              onClick={() => {
                window.print();
              }}
              className="flex-1 flex items-center justify-center gap-3 py-5 border-2 border-blue-600 text-blue-600 rounded-3xl font-black hover:bg-blue-50 transition-all active:scale-95"
            >
              <Printer size={24} />
              Cetak Struk
            </button>
            <button
              onClick={() => setLastTransaction(null)}
              className="flex-1 py-5 bg-blue-600 text-white rounded-3xl font-black text-lg hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 active:scale-95"
            >
              Transaksi Baru
            </button>
          </div>
        </div>
      )}

      {lastTransaction && (
        <div className="print-only fixed top-0 left-0 bg-white w-full h-full z-[100]">
          <Receipt transaction={lastTransaction} />
        </div>
      )}
    </div>
  );
};

export default Cashier;

import React, { useState, useMemo } from 'react';
import { PackagePlus, Edit2, ArrowUpDown, Filter, Trash2, Search, Plus, Check, ChevronDown, SortAsc, SortDesc, X, AlertTriangle, ImageIcon, ScanLine } from 'lucide-react';
import { Product, UnitType } from '../types';
import { formatCurrency, generateId } from '../utils';

interface InventoryProps {
  products: Product[];
  onAddStock: (id: string, amount: number) => void;
  onUpdateProduct: (product: Product) => void;
  onAddProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
}

type SortOrder = 'asc' | 'desc' | 'none';

const Inventory: React.FC<InventoryProps> = ({ products, onAddStock, onUpdateProduct, onAddProduct, onDeleteProduct }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [quickEditingStockId, setQuickEditingStockId] = useState<string | null>(null);
  const [stockAmount, setStockAmount] = useState<string>('');
  const [selectedCategory, setSelectedCategory] = useState<string>('Semua');
  const [sortOrder, setSortOrder] = useState<SortOrder>('none');
  const [showCategoryMenu, setShowCategoryMenu] = useState(false);
  const [showFormModal, setShowFormModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentProductId, setCurrentProductId] = useState<string | null>(null);
  const [productToDelete, setProductToDelete] = useState<{id: string, name: string} | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    barcode: '',
    price: '',
    category: '',
    stock: '',
    minStock: '',
    unit: UnitType.PCS,
    imageUrl: ''
  });

  const categories = useMemo(() => {
    const cats = Array.from(new Set(products.map(p => p.category)));
    return ['Semua', ...cats];
  }, [products]);

  const processedProducts = useMemo(() => {
    let result = products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm));
      const matchesCategory = selectedCategory === 'Semua' || p.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });

    if (sortOrder === 'asc') {
      result.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sortOrder === 'desc') {
      result.sort((a, b) => b.name.localeCompare(a.name));
    }

    return result;
  }, [products, searchTerm, selectedCategory, sortOrder]);

  const handleQuickStockUpdate = (id: string) => {
    const amt = Number(stockAmount);
    if (!isNaN(amt) && amt !== 0) {
      onAddStock(id, amt);
      setQuickEditingStockId(null);
      setStockAmount('');
    }
  };

  const openAddModal = () => {
    setIsEditing(false);
    setCurrentProductId(null);
    setFormData({
      name: '',
      barcode: '',
      price: '',
      category: '',
      stock: '',
      minStock: '',
      unit: UnitType.PCS,
      imageUrl: ''
    });
    setShowFormModal(true);
  };

  const openEditModal = (product: Product) => {
    setIsEditing(true);
    setCurrentProductId(product.id);
    setFormData({
      name: product.name,
      barcode: product.barcode || '',
      price: product.price.toString(),
      category: product.category,
      stock: product.stock.toString(),
      minStock: product.minStock.toString(),
      unit: product.unit,
      imageUrl: product.imageUrl || ''
    });
    setShowFormModal(true);
  };

  const confirmDelete = () => {
    if (productToDelete) {
      onDeleteProduct(productToDelete.id);
      setProductToDelete(null);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.price || !formData.category) {
      alert("Mohon lengkapi data produk!");
      return;
    }

    const productData: Product = {
      id: isEditing && currentProductId ? currentProductId : generateId(),
      barcode: formData.barcode,
      name: formData.name,
      price: Number(formData.price),
      category: formData.category,
      stock: Number(formData.stock) || 0,
      minStock: Number(formData.minStock) || 0,
      unit: formData.unit as UnitType,
      imageUrl: formData.imageUrl
    };

    if (isEditing) {
      onUpdateProduct(productData);
    } else {
      onAddProduct(productData);
    }

    setShowFormModal(false);
  };

  const toggleSort = () => {
    setSortOrder(prev => {
      if (prev === 'none') return 'asc';
      if (prev === 'asc') return 'desc';
      return 'none';
    });
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-800">Manajemen Stok</h2>
          <p className="text-gray-500 font-medium">Kelola inventori dan ketersediaan barang.</p>
        </div>
        <div className="flex gap-2">
           <button 
             onClick={openAddModal}
             className="flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-2xl font-black shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
           >
             <PackagePlus size={20} />
             Tambah Produk Baru
           </button>
        </div>
      </header>

      <div className="bg-white rounded-[2rem] border border-gray-100 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex flex-col md:flex-row gap-4 items-center justify-between bg-gray-50/30">
          <div className="relative w-full md:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Cari nama atau barcode..."
              className="w-full pl-11 pr-4 py-3 bg-white border border-transparent rounded-xl shadow-sm focus:ring-2 focus:ring-blue-100 focus:outline-none transition-all text-gray-900 font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex gap-2 relative w-full md:w-auto">
            <button 
              onClick={() => setShowCategoryMenu(!showCategoryMenu)}
              className={`flex-1 md:flex-none flex items-center justify-between gap-3 px-5 py-3 rounded-xl transition-all border ${
                selectedCategory !== 'Semua' 
                  ? 'bg-blue-600 border-blue-600 text-white font-bold' 
                  : 'bg-white border-gray-100 text-gray-500 hover:border-blue-200'
              }`}
            >
              <div className="flex items-center gap-2">
                <Filter size={18} />
                <span className="text-sm uppercase tracking-wider">{selectedCategory}</span>
              </div>
              <ChevronDown size={14} className={`transition-transform duration-200 ${showCategoryMenu ? 'rotate-180' : ''}`} />
            </button>

            {showCategoryMenu && (
              <>
                <div className="fixed inset-0 z-10" onClick={() => setShowCategoryMenu(false)}></div>
                <div className="absolute right-0 mt-14 w-56 bg-white border border-gray-100 rounded-2xl shadow-2xl z-20 py-2 animate-in fade-in zoom-in-95 duration-200">
                  <p className="px-4 py-2 text-[10px] font-black text-gray-400 uppercase tracking-widest border-b border-gray-50 mb-1">Pilih Kategori</p>
                  {categories.map(cat => (
                    <button
                      key={cat}
                      onClick={() => {
                        setSelectedCategory(cat);
                        setShowCategoryMenu(false);
                      }}
                      className="w-full flex items-center justify-between px-4 py-3 text-sm font-bold text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-colors"
                    >
                      {cat}
                      {selectedCategory === cat && <Check size={16} />}
                    </button>
                  ))}
                </div>
              </>
            )}

            <button 
              onClick={toggleSort}
              className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-5 py-3 rounded-xl transition-all border bg-white border-gray-100 text-gray-500 hover:border-blue-200 font-bold`}
            >
              {sortOrder === 'desc' ? <SortDesc size={18} /> : (sortOrder === 'asc' ? <SortAsc size={18} /> : <ArrowUpDown size={18} />)}
              <span className="text-sm uppercase tracking-wider">Sort</span>
            </button>
          </div>
        </div>

        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white text-gray-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <th className="px-8 py-5 border-b border-gray-100">Info Produk</th>
                <th className="px-8 py-5 border-b border-gray-100">Barcode</th>
                <th className="px-8 py-5 border-b border-gray-100">Harga Jual</th>
                <th className="px-8 py-5 border-b border-gray-100">Stok</th>
                <th className="px-8 py-5 border-b border-gray-100">Status</th>
                <th className="px-8 py-5 border-b border-gray-100 text-center">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {processedProducts.length > 0 ? (
                processedProducts.map(product => (
                  <tr key={product.id} className="hover:bg-blue-50/20 transition-colors group animate-in slide-in-from-left-2 duration-300">
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-14 h-14 bg-gray-50 rounded-2xl border border-gray-100 overflow-hidden shadow-sm flex-shrink-0">
                          {product.imageUrl ? (
                            <img src={product.imageUrl} className="w-full h-full object-cover" />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center text-gray-300">
                              <ImageIcon size={24} />
                            </div>
                          )}
                        </div>
                        <div>
                          <span className="font-black text-gray-800 block leading-tight">{product.name}</span>
                          <span className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">{product.category}</span>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                       <div className="flex items-center gap-2 text-gray-500">
                          <ScanLine size={14} className="text-blue-500" />
                          <span className="font-mono text-xs font-bold">{product.barcode || '-'}</span>
                       </div>
                    </td>
                    <td className="px-8 py-6">
                      <span className="font-black text-gray-900">{formatCurrency(product.price)}</span>
                    </td>
                    <td className="px-8 py-6">
                      {quickEditingStockId === product.id ? (
                        <div className="flex items-center gap-2">
                          <input 
                             type="number"
                             className="w-20 p-2 border-2 border-blue-100 rounded-xl focus:outline-none focus:border-blue-500 text-gray-900 font-black text-center"
                             placeholder="+/-"
                             value={stockAmount}
                             onChange={(e) => setStockAmount(e.target.value)}
                             autoFocus
                          />
                          <button 
                            onClick={() => handleQuickStockUpdate(product.id)}
                            className="w-9 h-9 flex items-center justify-center bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-colors shadow-lg shadow-blue-100"
                          >
                            <Check size={18} />
                          </button>
                        </div>
                      ) : (
                        <div className="flex items-center gap-2">
                          <span className={`font-black text-lg ${product.stock <= product.minStock ? 'text-red-600' : 'text-gray-800'}`}>
                            {product.stock}
                          </span>
                          <span className="text-[10px] font-bold text-gray-400 uppercase">{product.unit}</span>
                          <button 
                             onClick={() => setQuickEditingStockId(product.id)}
                             className="opacity-0 group-hover:opacity-100 w-8 h-8 flex items-center justify-center text-blue-500 bg-blue-50 rounded-lg transition-all active:scale-90"
                             title="Update Stok"
                          >
                            <Plus size={16} />
                          </button>
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-6">
                      {product.stock <= product.minStock ? (
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-red-50 text-red-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-red-100 w-fit">
                          <AlertTriangle size={12} />
                          Low Stock
                        </div>
                      ) : (
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-green-50 text-green-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-green-100 w-fit">
                          <Check size={12} />
                          Aman
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center justify-center gap-3">
                        <button 
                          onClick={() => openEditModal(product)}
                          className="w-10 h-10 flex items-center justify-center text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all active:scale-90 border border-transparent hover:border-blue-100"
                        >
                          <Edit2 size={18} />
                        </button>
                        <button 
                          onClick={() => setProductToDelete({id: product.id, name: product.name})}
                          className="w-10 h-10 flex items-center justify-center text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all active:scale-90 border border-transparent hover:border-red-100"
                        >
                          <Trash2 size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={6} className="px-8 py-32 text-center">
                    <div className="flex flex-col items-center justify-center text-gray-300">
                      <Search size={64} className="mb-4 opacity-10" />
                      <p className="font-bold text-lg">Produk tidak ditemukan</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showFormModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">
            <div className="p-8 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
              <h3 className="text-2xl font-black text-gray-800 tracking-tight">
                {isEditing ? 'Detail Produk' : 'Produk Baru'}
              </h3>
              <button onClick={() => setShowFormModal(false)} className="w-10 h-10 flex items-center justify-center bg-white rounded-full text-gray-400 hover:text-gray-600 transition-all shadow-sm">
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-10 space-y-8 overflow-y-auto custom-scrollbar">
              <div className="space-y-6">
                <div>
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-2 ml-1">Nama Produk</label>
                  <input 
                    type="text"
                    required
                    placeholder="Contoh: Beras Premium 5kg"
                    className="w-full p-4 bg-gray-50 border-2 border-gray-50 rounded-2xl focus:outline-none focus:border-blue-500 focus:bg-white font-bold text-gray-900 transition-all shadow-inner"
                    value={formData.name}
                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                  />
                </div>

                <div>
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-2 ml-1">Barcode (Opsional)</label>
                  <div className="relative">
                    <ScanLine className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" size={20} />
                    <input 
                      type="text"
                      placeholder="899123456XXX"
                      className="w-full p-4 pl-12 bg-gray-50 border-2 border-gray-50 rounded-2xl focus:outline-none focus:border-blue-500 focus:bg-white font-mono text-gray-900 transition-all shadow-inner"
                      value={formData.barcode}
                      onChange={(e) => setFormData({...formData, barcode: e.target.value})}
                    />
                  </div>
                </div>

                <div>
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-2 ml-1">URL Foto Produk</label>
                  <div className="relative">
                    <ImageIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" size={20} />
                    <input 
                      type="url"
                      placeholder="https://images.unsplash.com/..."
                      className="w-full p-4 pl-12 bg-gray-50 border-2 border-gray-50 rounded-2xl focus:outline-none focus:border-blue-500 focus:bg-white font-medium text-gray-900 transition-all shadow-inner text-sm"
                      value={formData.imageUrl}
                      onChange={(e) => setFormData({...formData, imageUrl: e.target.value})}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-2 ml-1">Kategori</label>
                    <input 
                      type="text"
                      required
                      placeholder="Sembako"
                      className="w-full p-4 bg-gray-50 border-2 border-gray-50 rounded-2xl focus:outline-none focus:border-blue-500 focus:bg-white font-bold text-gray-900 transition-all shadow-inner"
                      value={formData.category}
                      onChange={(e) => setFormData({...formData, category: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-2 ml-1">Satuan</label>
                    <select 
                      className="w-full p-4 bg-gray-50 border-2 border-gray-50 rounded-2xl focus:outline-none focus:border-blue-500 focus:bg-white font-bold text-gray-900 transition-all shadow-inner appearance-none cursor-pointer"
                      value={formData.unit}
                      onChange={(e) => setFormData({...formData, unit: e.target.value as UnitType})}
                    >
                      {Object.values(UnitType).map(u => (
