            <div className="p-8 border-t border-gray-100 bg-gray-50">
              <button onClick={handleCheckout} className="w-full py-6 bg-blue-600 text-white rounded-3xl font-black text-2xl shadow-2xl">Konfirmasi Pembayaran</button>
