                ].map(method => (
                  <button
                    key={method.id}
                    onClick={() => { setPaymentMethod(method.id as PaymentMethod); setSelectedProvider(''); }}
                    className={`flex flex-col items-center gap-3 p-6 rounded-[2rem] border-2 transition-all ${paymentMethod === method.id ? 'border-blue-600 bg-blue-600 text-white shadow-xl shadow-blue-100' : 'border-gray-100 text-gray-400 bg-gray-50'}`}
                  >
                    <method.icon size={28} />
                    <span className="text-xs font-black tracking-wider">{method.label}</span>
                  </button>
                ))}
              </div>
              {paymentMethod === PaymentMethod.CASH && (
                <div className="space-y-6">
                  <div className="grid grid-cols-3 gap-3">
                    {quickDenominations.map(val => (
                      <button key={val} onClick={() => addDenomination(val)} className="py-3 bg-white text-gray-700 font-black rounded-2xl border border-gray-200 text-sm hover:bg-blue-50 transition-colors">+{val/1000}rb</button>
                    ))}
                    <button onClick={() => setAmountPaid(cartTotal.toString())} className="py-3 bg-blue-50 text-blue-600 font-black rounded-2xl border border-blue-100 text-sm col-span-3 transition-all hover:bg-blue-100">UANG PAS ({formatCurrency(cartTotal)})</button>
                  </div>
                  <div className="space-y-3">
                    <div className="relative group">
                      <span className="absolute left-6 top-1/2 -translate-y-1/2 font-black text-gray-400 text-xl">Rp</span>
                      <input type="text" inputMode="numeric" autoFocus onFocus={(e) => e.target.select()} className="w-full p-6 pl-16 pr-12 bg-gray-50 border border-gray-200 rounded-3xl font-black text-3xl text-right text-gray-900 focus:bg-white transition-all focus:ring-4 focus:ring-blue-100 focus:outline-none" value={amountPaid} onChange={handleManualAmountChange} />
                    </div>
                    {Number(amountPaid) >= cartTotal && (
                      <div className="flex justify-between items-center p-6 bg-green-50 rounded-3xl border border-green-100">
                        <span className="text-sm text-green-700 font-black uppercase tracking-wider">Kembalian</span>
                        <span className="font-black text-green-700 text-3xl">{formatCurrency(change)}</span>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
            <div className="p-8 border-t border-gray-100 bg-gray-50">
              <button onClick={handleCheckout} className="w-full py-6 bg-blue-600 text-white rounded-3xl font-black text-2xl shadow-2xl shadow-blue-100 hover:bg-blue-700 active:scale-95 transition-all">Konfirmasi Pembayaran</button>
            </div>
          </div>
        </div>
      )}

      {lastTransaction && !showCheckoutModal && (
        <div className="fixed inset-0 bg-white z-[60] flex flex-col items-center justify-center p-6 no-print">
          <div className="text-center mb-8">
            <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6 animate-bounce"><CheckCircle2 size={56} /></div>
            <h2 className="text-4xl font-black text-gray-800 tracking-tight">Pembayaran Sukses!</h2>
            <p className="text-gray-400 mt-2 font-medium">No. Transaksi: <span className="text-gray-800 font-black">{lastTransaction.id}</span></p>
          </div>
          <div className="flex gap-4 w-full max-w-md">
            <button onClick={() => window.print()} className="flex-1 flex items-center justify-center gap-3 py-5 border-2 border-blue-600 text-blue-600 rounded-3xl font-black hover:bg-blue-50 transition-all"><Printer size={24} />Cetak Struk</button>
            <button onClick={() => setLastTransaction(null)} className="flex-1 py-5 bg-blue-600 text-white rounded-3xl font-black text-lg hover:bg-blue-700 transition-all shadow-xl shadow-blue-100">Transaksi Baru</button>
          </div>
        </div>
      )}

      {lastTransaction && (
        <div className="print-only fixed top-0 left-0 bg-white w-full h-full z-[100]">
