              </div>
              <div className="grid grid-cols-3 gap-4">
                {[
                  { id: PaymentMethod.CASH, label: 'TUNAI', icon: Banknote },
                  { id: PaymentMethod.QRIS, label: 'QRIS', icon: QrCode },
                  { id: PaymentMethod.TRANSFER, label: 'DIGITAL', icon: Send },
                ].map(method => (
                  <button
                    key={method.id}
                    onClick={() => { setPaymentMethod(method.id as PaymentMethod); setSelectedProvider(''); }}
                    className={`flex flex-col items-center gap-3 p-6 rounded-[2rem] border-2 transition-all ${paymentMethod === method.id ? 'border-blue-600 bg-blue-600 text-white shadow-xl shadow-blue-100' : 'border-gray-100 text-gray-400 bg-gray-50'}`}
                  >
                    <method.icon size={28} />
