            <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center">
               <div className="w-72 h-48 border-2 border-blue-500 rounded-3xl relative">
                <div className="absolute top-0 left-0 w-full h-1 bg-blue-400 shadow-[0_0_15px_#3b82f6] animate-[scan_2s_infinite]"></div>
              </div>
              <p className="mt-6 text-white/60 font-black uppercase tracking-widest text-[10px]">Posisikan Barcode di Tengah</p>
            </div>

            {scanResult && (
              <div className="absolute inset-x-0 bottom-10 flex justify-center px-4 animate-in slide-in-from-bottom-2">
                <div className={`px-6 py-4 rounded-2xl shadow-2xl border flex items-center gap-3 bg-white text-gray-900`}>
                  <CheckCircle2 size={24} className="text-green-500" />
