          <div className="mt-8 w-full max-w-md space-y-4">
            <form onSubmit={handleManualBarcodeScan} className="relative">
              <input name="barcode" type="text" autoFocus placeholder="Ketik barcode manual..." className="w-full p-5 pl-6 bg-white/10 border border-white/20 rounded-2xl text-white text-center font-mono tracking-widest focus:outline-none focus:ring-4 focus:ring-blue-500/50" />
              <button type="submit" className="absolute right-3 top-1/2 -translate-y-1/2 p-2 bg-blue-600 text-white rounded-xl"><CheckCircle2 size={24} /></button>
            </form>
            <button onClick={() => setShowBarcodeList(!showBarcodeList)} className="w-full text-white/40 text-xs font-bold hover:text-white transition-colors uppercase tracking-widest py-2">Lihat Daftar Kode Produk</button>
            {showBarcodeList && (
               <div className="bg-white/5 backdrop-blur-md rounded-2xl p-6 max-h-40 overflow-y-auto custom-scrollbar border border-white/10">
                  <div className="grid grid-cols-1 gap-3">
                    {products.filter(p => p.barcode).map(p => (
                      <div key={p.id} className="flex justify-between items-center text-xs">
                        <span className="text-white/60">{p.name}</span>
                        <code className="bg-blue-600/40 text-blue-200 px-3 py-1 rounded-lg font-mono font-black">{p.barcode}</code>
                      </div>
                    ))}
                  </div>
               </div>
            )}
          </div>
          <style>{`@keyframes scan { 0% { transform: translateY(0); } 50% { transform: translateY(192px); } 100% { transform: translateY(0); } }`}</style>
        </div>
      )}

      {showCheckoutModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95">
              <div className="p-8 flex justify-between items-center border-b border-gray-100">
                <h3 className="text-2xl font-black text-gray-800">Checkout</h3>
                <button onClick={() => setShowCheckoutModal(false)} className="w-10 h-10 flex items-center justify-center bg-gray-100 rounded-full"><X size={20} /></button>
              </div>
              <div className="p-8 space-y-8">
                <div className="text-center bg-blue-50 py-10 rounded-[2.5rem] border-2 border-blue-100">
                  <p className="text-blue-600 font-bold uppercase tracking-widest text-xs mb-1">Total Bayar</p>
                  <p className="text-5xl font-black text-blue-600">{formatCurrency(cartTotal)}</p>
                </div>
                <div className="space-y-4">
                  <div className="flex gap-2">
                    {Object.values(PaymentMethod).map(method => (
                      <button 
                        key={method} 
                        onClick={() => setPaymentMethod(method)}
                        className={`flex-1 py-4 rounded-2xl font-bold text-xs border-2 transition-all ${paymentMethod === method ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white border-gray-100 text-gray-400'}`}
                      >
                        {method}
                      </button>
                    ))}
                  </div>
                  {paymentMethod === PaymentMethod.CASH && (
                    <div className="space-y-4">
                      <input 
                        type="number" 
                        placeholder="Jumlah Uang..." 
                        className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-2xl font-black text-2xl text-center focus:border-blue-500 focus:outline-none"
                        value={amountPaid}
                        onChange={(e) => setAmountPaid(e.target.value)}
                      />
                      <div className="grid grid-cols-3 gap-2">
                        {quickDenominations.map(d => (
                          <button key={d} onClick={() => setAmountPaid(d.toString())} className="py-3 bg-gray-100 rounded-xl text-xs font-bold hover:bg-gray-200">+{d/1000}rb</button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
                <button onClick={handleCheckout} className="w-full py-6 bg-blue-600 text-white rounded-[2rem] font-black text-2xl shadow-2xl shadow-blue-200 hover:bg-blue-700 active:scale-95 transition-all">Selesaikan Pesanan</button>
              </div>
           </div>
        </div>
      )}

      {lastTransaction && !showCheckoutModal && (
        <div className="fixed inset-0 bg-white z-[120] flex flex-col items-center justify-center p-6 text-center">
          <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6 animate-bounce">
             <CheckCircle2 size={56} />
          </div>
          <h2 className="text-4xl font-black text-gray-800 mb-2">Berhasil!</h2>
          <p className="text-gray-400 font-bold mb-10 text-lg">Kembalian: <span className="text-green-600">{formatCurrency(lastTransaction.change)}</span></p>
          <div className="flex flex-col gap-4 w-full max-w-sm">
            <button onClick={() => window.print()} className="w-full py-5 border-4 border-blue-600 text-blue-600 rounded-[2rem] font-black text-lg hover:bg-blue-50 transition-all">Cetak Struk</button>
            <button onClick={() => setLastTransaction(null)} className="w-full py-5 bg-blue-600 text-white rounded-[2rem] font-black text-lg shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all">Transaksi Baru</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Cashier;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Search, Plus, Minus, Trash2, Banknote, CreditCard, Send, Printer, CheckCircle2, X, ShoppingCart, QrCode, Building2, Wallet, ImageIcon, ScanLine, Camera, Flashlight, List, Loader2, RefreshCw } from 'lucide-react';
import { Product, CartItem, PaymentMethod, Transaction } from '../types';
import { formatCurrency, generateId } from '../utils';
import Receipt from './Receipt';
import { Html5Qrcode } from 'html5-qrcode';

interface CashierProps {
  products: Product[];
  onCompleteTransaction: (transaction: Transaction) => void;
}

const Cashier: React.FC<CashierProps> = ({ products, onCompleteTransaction }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showCheckoutModal, setShowCheckoutModal] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [showBarcodeList, setShowBarcodeList] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [amountPaid, setAmountPaid] = useState<string>('');
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [scanResult, setScanResult] = useState<string | null>(null);
  const [isFlashOn, setIsFlashOn] = useState(false);
  const [isCameraInitializing, setIsCameraInitializing] = useState(false);

  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const lastScannedCode = useRef<string | null>(null);
  const scanTimeout = useRef<number | null>(null);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const playBeep = () => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = audioCtx.createOscillator();
      const gainNode = audioCtx.createGain();
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.type = 'sine';
      oscillator.frequency.setValueAtTime(880, audioCtx.currentTime);
      gainNode.gain.setValueAtTime(0.1, audioCtx.currentTime);
      oscillator.start();
      oscillator.stop(audioCtx.currentTime + 0.1);

      // HP Vibration feedback
      if ('vibrate' in navigator) {
        navigator.vibrate(100);
      }
    } catch (e) {}
  };

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => 
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    playBeep();
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const startScanner = async () => {
    setShowScanner(true);
    setScanResult(null);
    setIsCameraInitializing(true);
    lastScannedCode.current = null;

    // Small delay to ensure the container is rendered
    setTimeout(async () => {
      try {
        const html5QrCode = new Html5Qrcode("reader");
        html5QrCodeRef.current = html5QrCode;

        const config = {
          fps: 15, // Higher FPS for smoother scanning
          qrbox: { width: 250, height: 150 }, // Barcode shaped box
          aspectRatio: 1.0,
          experimentalFeatures: {
            useBarCodeDetectorIfSupported: true
          }
        };

        await html5QrCode.start(
          { facingMode: "environment" }, 
          config,
          (decodedText) => {
            if (lastScannedCode.current === decodedText) return;

            lastScannedCode.current = decodedText;
            const found = products.find(p => p.barcode === decodedText);

            if (found) {
              addToCart(found);
              setScanResult(`OK: ${found.name}`);
            } else {
              setScanResult(`KODE TIDAK DIKENAL: ${decodedText}`);
            }

            if (scanTimeout.current) window.clearTimeout(scanTimeout.current);
            scanTimeout.current = window.setTimeout(() => {
              lastScannedCode.current = null;
              setScanResult(null);
            }, 1800);
          },
          () => {} // Ignoring errors during search
        );
        setIsCameraInitializing(false);
      } catch (err) {
        console.error("Scanner Error:", err);
        setIsCameraInitializing(false);
        alert("Gagal memutar kamera. Silakan periksa izin kamera di pengaturan HP Anda.");
        setShowScanner(false);
      }
    }, 500);
  };

  const stopScanner = async () => {
    if (html5QrCodeRef.current) {
      try {
        if (html5QrCodeRef.current.isScanning) {
          await html5QrCodeRef.current.stop();
        }
        html5QrCodeRef.current = null;
      } catch (err) {
        console.error("Stop Error:", err);
      }
    }
    setShowScanner(false);
    setShowBarcodeList(false);
    setIsFlashOn(false);
    setScanResult(null);
  };

  const toggleFlash = async () => {
    if (html5QrCodeRef.current && html5QrCodeRef.current.isScanning) {
      try {
        const track = html5QrCodeRef.current.getRunningTrack();
        // @ts-ignore
        const capabilities = track?.getCapabilities();
        // @ts-ignore
        if (capabilities?.torch) {
          const newFlashState = !isFlashOn;
          // @ts-ignore
          await track.applyConstraints({ advanced: [{ torch: newFlashState }] });
          setIsFlashOn(newFlashState);
        } else {
          alert("Lampu senter tidak tersedia di HP/Browser ini.");
        }
      } catch (err) {
        console.error("Flash Error:", err);
      }
    }
  };

  useEffect(() => {
    return () => {
      if (html5QrCodeRef.current) {
        html5QrCodeRef.current.stop().catch(() => {});
      }
    };
  }, []);

  const handleManualBarcodeScan = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const input = (e.currentTarget.elements.namedItem('barcode') as HTMLInputElement);
    const barcodeValue = input.value;
    const found = products.find(p => p.barcode === barcodeValue);
    if (found) {
      addToCart(found);
      setScanResult(`Berhasil: ${found.name}`);
      setTimeout(() => setScanResult(null), 1500);
      input.value = '';
    } else {
      setScanResult('Tidak terdaftar');
      setTimeout(() => setScanResult(null), 1500);
    }
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const change = Number(amountPaid) - cartTotal;
  const quickDenominations = [2000, 5000, 10000, 20000, 50000, 100000];

  const handleCheckout = () => {
    if (cart.length === 0) return;
    const transaction: Transaction = {
      id: `TRX-${generateId()}`,
      date: new Date().toISOString(),
      items: [...cart],
      total: cartTotal,
      paymentMethod,
      amountPaid: paymentMethod === PaymentMethod.CASH ? Number(amountPaid) : cartTotal,
      change: paymentMethod === PaymentMethod.CASH ? Math.max(0, change) : 0,
    };
    onCompleteTransaction(transaction);
    setLastTransaction(transaction);
    setCart([]);
    setAmountPaid('');
    setShowCheckoutModal(false);
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-120px)] animate-in slide-in-from-bottom-4 duration-500">
      {/* Product List Section */}
      <div className="flex-1 flex flex-col gap-6 no-print">
        <div className="flex gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="Cari produk..."
              className="w-full pl-12 pr-4 py-4 bg-white rounded-2xl border border-gray-100 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all text-gray-900"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={startScanner}
            className="px-6 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-100 flex items-center gap-2 font-black hover:bg-blue-700 transition-all active:scale-95"
          >
            <ScanLine size={24} />
            <span className="hidden sm:inline">Scan HP</span>
            <span className="sm:hidden">Scan</span>
          </button>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto pb-4 pr-2 custom-scrollbar">
          {filteredProducts.map(product => (
            <button
              key={product.id}
              onClick={() => addToCart(product)}
              disabled={product.stock <= 0}
              className={`flex flex-col bg-white rounded-3xl border border-gray-100 shadow-sm hover:shadow-xl transition-all active:scale-95 text-left group overflow-hidden ${product.stock <= 0 ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              <div className="relative h-32 overflow-hidden bg-gray-50">
                {product.imageUrl ? (
                  <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-gray-300">
                    <ImageIcon size={40} />
                  </div>
                )}
                <div className="absolute top-2 right-2 flex flex-col gap-1 items-end">
                   <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider shadow-sm ${product.stock <= product.minStock ? 'bg-red-500 text-white' : 'bg-white/90 text-gray-800'}`}>
                    SISA: {product.stock}
                  </span>
                  {product.barcode && (
                    <span className="px-2 py-1 bg-gray-900 text-white rounded-md text-[9px] font-black shadow-lg">
                      {product.barcode}
                    </span>
                  )}
                </div>
              </div>
              <div className="p-3 flex-1 flex flex-col">
                <span className="text-[9px] font-bold text-blue-500 uppercase tracking-widest mb-1">{product.category}</span>
                <h4 className="font-bold text-gray-800 text-xs line-clamp-2 mb-2 flex-1 leading-snug">{product.name}</h4>
                <p className="text-blue-600 font-black text-sm">{formatCurrency(product.price)}</p>
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Cart Section */}
      <div className="w-full lg:w-[400px] bg-white rounded-3xl border border-gray-100 shadow-xl flex flex-col no-print overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-gray-50/30">
          <h3 className="text-xl font-bold text-gray-800">Keranjang</h3>
          <span className="px-3 py-1 bg-blue-600 text-white rounded-full text-xs font-black">{cart.length}</span>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-300">
              <ShoppingCart className="w-12 h-12 mb-4 opacity-20" />
              <p className="text-sm font-bold opacity-40">Keranjang Kosong</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex items-center gap-3 p-3 bg-gray-50 rounded-2xl border border-transparent hover:border-blue-100 transition-all">
                <div className="w-10 h-10 rounded-xl bg-white overflow-hidden shadow-sm border border-gray-100 flex-shrink-0">
                  <img src={item.imageUrl} className="w-full h-full object-cover" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-bold text-gray-800 text-xs truncate">{item.name}</p>
                  <p className="text-blue-600 text-[10px] font-black">{formatCurrency(item.price)}</p>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => updateQuantity(item.id, -1)} className="w-7 h-7 flex items-center justify-center bg-white text-gray-400 hover:text-red-500 rounded-lg shadow-sm border border-gray-100"><Minus size={14} /></button>
                  <span className="w-5 text-center font-black text-gray-800 text-xs">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.id, 1)} className="w-7 h-7 flex items-center justify-center bg-white text-blue-600 rounded-lg shadow-sm border border-gray-100"><Plus size={14} /></button>
                </div>
              </div>
            ))
          )}
        </div>
        <div className="p-6 bg-gray-100 border-t border-gray-200 space-y-4">
          <div className="flex justify-between items-center">
            <span className="font-bold text-gray-500 uppercase tracking-widest text-[10px]">Total Bayar</span>
            <span className="text-3xl font-black text-blue-600">{formatCurrency(cartTotal)}</span>
          </div>
          <button onClick={() => setShowCheckoutModal(true)} disabled={cart.length === 0} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl shadow-blue-200 hover:bg-blue-700 active:scale-95 transition-all disabled:opacity-50">BAYAR SEKARANG</button>
        </div>
      </div>

      {/* FULL SCREEN SCANNER MODAL FOR HP */}
      {showScanner && (
        <div className="fixed inset-0 bg-black z-[2000] flex flex-col items-center justify-center animate-in fade-in duration-300 overflow-hidden">
          {/* Top Controls */}
          <div className="absolute top-0 inset-x-0 p-8 flex justify-between items-center z-[2010]">
            <button 
              onClick={toggleFlash} 
              className={`w-14 h-14 flex items-center justify-center rounded-full transition-all ${isFlashOn ? 'bg-yellow-400 text-black shadow-[0_0_20px_rgba(250,204,21,0.5)]' : 'bg-white/10 text-white'}`}
            >
              <Flashlight size={28} />
            </button>
            <h2 className="text-white text-sm font-black tracking-[0.3em] uppercase">Scanner HP</h2>
            <button onClick={stopScanner} className="w-14 h-14 flex items-center justify-center bg-white/10 text-white rounded-full hover:bg-white/20 transition-all">
              <X size={28} />
            </button>
          </div>

          {/* Main Scanner Body */}
          <div className="relative w-full h-full flex items-center justify-center p-6">
            <div id="reader" className="w-full max-w-lg aspect-square rounded-[3rem] overflow-hidden border-4 border-white/10 shadow-2xl bg-gray-900 relative z-[2005]">
              {isCameraInitializing && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-900 z-20">
                  <RefreshCw className="w-12 h-12 text-blue-500 animate-spin mb-4" />
                  <p className="text-white text-xs font-black uppercase tracking-widest">Membuka Kamera...</p>
                </div>
              )}
            </div>

            {/* Focus Overlay */}
            <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center z-[2006]">
              <div className="w-72 h-44 border-2 border-dashed border-blue-400/50 rounded-3xl relative">
                <div className="absolute top-0 left-0 w-full h-1 bg-blue-500 shadow-[0_0_20px_#3b82f6] animate-[scan_2s_infinite]"></div>
              </div>
              <p className="mt-8 text-white/40 font-black uppercase tracking-widest text-[10px]">Dekatkan Barcode ke Kotak</p>
            </div>

            {/* Success Overlay */}
            {scanResult && (
              <div className="absolute inset-x-0 top-1/4 flex justify-center px-4 z-[2008] animate-in zoom-in-95">
                <div className={`px-8 py-4 rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.5)] border-2 border-white/20 flex items-center gap-3 bg-white text-gray-900`}>
                  <div className="w-8 h-8 rounded-full bg-green-100 flex items-center justify-center text-green-600">
                    <CheckCircle2 size={20} />
                  </div>
