                </div>
              </div>
              <div className="p-3 flex-1 flex flex-col">
                <span className="text-[9px] font-bold text-blue-500 uppercase tracking-widest mb-1">{product.category}</span>
                <h4 className="font-bold text-gray-800 text-xs line-clamp-2 mb-2 flex-1 leading-snug">{product.name}</h4>
