                      <button 
                        key={method} 
                        onClick={() => { setPaymentMethod(method); setAmountPaid(''); }}
                        className={`flex-1 py-4 rounded-2xl font-black text-[10px] uppercase tracking-wider border-2 transition-all ${paymentMethod === method ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-white border-gray-100 text-gray-400 hover:border-blue-200'}`}
                      >
                        {method}
                      </button>
                    ))}
                  </div>
                  {paymentMethod === PaymentMethod.CASH && (
                    <div className="space-y-4 animate-in slide-in-from-top-4">
                      <div className="relative">
                        <span className="absolute left-6 top-1/2 -translate-y-1/2 font-black text-gray-300 text-2xl">Rp</span>
                        <input 
                          type="number" 
                          placeholder="Jumlah Uang..." 
                          className="w-full p-6 pl-16 bg-gray-50 border-2 border-gray-100 rounded-[2rem] font-black text-4xl text-right focus:border-blue-500 focus:bg-white focus:outline-none transition-all"
                          value={amountPaid}
                          onChange={(e) => setAmountPaid(e.target.value)}
                          autoFocus
                        />
                      </div>
                      <div className="grid grid-cols-3 gap-2">
                        {quickDenominations.map(d => (
                          <button key={d} onClick={() => setAmountPaid(d.toString())} className="py-4 bg-gray-50 rounded-2xl text-[10px] font-black hover:bg-blue-50 hover:text-blue-600 transition-all border border-transparent hover:border-blue-100">+{d/1000}rb</button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
                <button onClick={handleCheckout} className="w-full py-6 bg-blue-600 text-white rounded-[2rem] font-black text-2xl shadow-2xl shadow-blue-200 hover:bg-blue-700 active:scale-95 transition-all">KONFIRMASI BAYAR</button>
              </div>
           </div>
        </div>
      )}

      {/* Success Transaction View */}
      {lastTransaction && !showCheckoutModal && (
        <div className="fixed inset-0 bg-white z-[120] flex flex-col items-center justify-center p-8 text-center animate-in fade-in zoom-in-110 duration-500">
          <div className="w-32 h-32 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-8 animate-bounce shadow-2xl shadow-green-100">
             <CheckCircle2 size={72} />
          </div>
          <h2 className="text-5xl font-black text-gray-800 mb-4 tracking-tighter">Berhasil!</h2>
          <div className="bg-gray-50 px-10 py-6 rounded-3xl border border-gray-100 mb-12">
            <p className="text-gray-400 font-bold uppercase tracking-[0.2em] text-xs mb-1">Uang Kembalian</p>
            <p className="text-5xl font-black text-green-600">{formatCurrency(lastTransaction.change)}</p>
          </div>
          <div className="flex flex-col sm:flex-row gap-4 w-full max-w-lg">
            <button onClick={() => window.print()} className="flex-1 py-6 border-4 border-blue-600 text-blue-600 rounded-[2.5rem] font-black text-xl hover:bg-blue-50 transition-all flex items-center justify-center gap-3">
              <Printer size={24} />
              Cetak Struk
            </button>
            <button onClick={() => setLastTransaction(null)} className="flex-1 py-6 bg-blue-600 text-white rounded-[2.5rem] font-black text-xl shadow-2xl shadow-blue-200 hover:bg-blue-700 active:scale-95 transition-all uppercase tracking-widest">Selesai</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Cashier;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Search, Plus, Minus, Trash2, Banknote, CreditCard, Send, Printer, CheckCircle2, X, ShoppingCart, QrCode, Building2, Wallet, ImageIcon, ScanLine, Camera, Flashlight, List, Loader2, RefreshCw } from 'lucide-react';
import { Product, CartItem, PaymentMethod, Transaction } from '../types';
import { formatCurrency, generateId } from '../utils';

interface CashierProps {
  products: Product[];
  onCompleteTransaction: (transaction: Transaction) => void;
}

const Cashier: React.FC<CashierProps> = ({ products, onCompleteTransaction }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showCheckoutModal, setShowCheckoutModal] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [showBarcodeList, setShowBarcodeList] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [amountPaid, setAmountPaid] = useState<string>('');
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [scanResult, setScanResult] = useState<string | null>(null);
  const [isCameraInitializing, setIsCameraInitializing] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const detectionFrameRef = useRef<number | null>(null);
  const lastScannedCode = useRef<string | null>(null);
  const barcodeBuffer = useRef<string>('');
  const lastKeyTime = useRef<number>(0);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const playBeep = () => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = audioCtx.createOscillator();
      const gainNode = audioCtx.createGain();
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.type = 'sine';
      oscillator.frequency.setValueAtTime(880, audioCtx.currentTime);
      gainNode.gain.setValueAtTime(0.1, audioCtx.currentTime);
      oscillator.start();
      oscillator.stop(audioCtx.currentTime + 0.1);

      // Getaran HP jika mendukung
      if ('vibrate' in navigator) {
        navigator.vibrate(100);
      }
    } catch (e) {}
  };

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => 
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    playBeep();
  };

  // 1. Fitur: Dukungan Alat Scanner Fisik (USB/Bluetooth)
  // Listener global untuk menangkap input cepat dari alat scanner eksternal
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      // Abaikan jika sedang mengetik di kolom pencarian
      if (document.activeElement?.tagName === 'INPUT') return;

      const currentTime = Date.now();

      // Scanner fisik biasanya mengirim karakter dengan jeda < 50ms
      if (currentTime - lastKeyTime.current > 50) {
        barcodeBuffer.current = '';
      }

      lastKeyTime.current = currentTime;

      if (e.key === 'Enter') {
        if (barcodeBuffer.current.length > 2) {
          const found = products.find(p => p.barcode === barcodeBuffer.current);
          if (found) {
            addToCart(found);
            setScanResult(`Scanner: ${found.name}`);
            setTimeout(() => setScanResult(null), 1500);
          }
          barcodeBuffer.current = '';
        }
      } else if (e.key.length === 1) {
        barcodeBuffer.current += e.key;
      }
    };

    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [products]);

  // 2. Fitur: Kamera HP Scanner (Native BarcodeDetector)
  const startScanner = async () => {
    setShowScanner(true);
    setIsCameraInitializing(true);
    setScanResult(null);
    lastScannedCode.current = null;

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: 'environment',
          width: { ideal: 1280 },
          height: { ideal: 720 }
        } 
      });

      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play();
          setIsCameraInitializing(false);
          initBarcodeDetection();
        };
      }
    } catch (err) {
      console.error("Gagal kamera:", err);
      alert("Pastikan izin kamera diberikan.");
      setShowScanner(false);
      setIsCameraInitializing(false);
    }
  };

  const initBarcodeDetection = () => {
    if (!('BarcodeDetector' in window)) {
      console.warn('BarcodeDetector API tidak didukung browser ini. Silakan gunakan Google Chrome di Android.');
      return;
    }

    // @ts-ignore
    const barcodeDetector = new window.BarcodeDetector({ 
      formats: ['ean_13', 'ean_8', 'code_128', 'qr_code', 'upc_a'] 
    });

    const detect = async () => {
      if (!videoRef.current || videoRef.current.paused || videoRef.current.ended) return;

      try {
        const barcodes = await barcodeDetector.detect(videoRef.current);
        if (barcodes.length > 0) {
          const codeValue = barcodes[0].rawValue;

          if (lastScannedCode.current !== codeValue) {
            lastScannedCode.current = codeValue;
            const found = products.find(p => p.barcode === codeValue);

            if (found) {
              addToCart(found);
              setScanResult(`Berhasil: ${found.name}`);
            } else {
              setScanResult(`Bukan Produk: ${codeValue}`);
            }

            setTimeout(() => {
              lastScannedCode.current = null;
              setScanResult(null);
            }, 2000);
          }
        }
      } catch (e) {}

      detectionFrameRef.current = requestAnimationFrame(detect);
    };

    detectionFrameRef.current = requestAnimationFrame(detect);
  };

  const stopScanner = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    if (detectionFrameRef.current) {
      cancelAnimationFrame(detectionFrameRef.current);
    }
    setShowScanner(false);
    setShowBarcodeList(false);
    setScanResult(null);
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const handleManualBarcodeScan = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const input = (e.currentTarget.elements.namedItem('barcode') as HTMLInputElement);
    const barcodeValue = input.value;
    const found = products.find(p => p.barcode === barcodeValue);
    if (found) {
      addToCart(found);
      setScanResult(`Ditambahkan: ${found.name}`);
      setTimeout(() => setScanResult(null), 1500);
      input.value = '';
    } else {
      setScanResult('Gagal: Produk tidak ada');
      setTimeout(() => setScanResult(null), 1500);
    }
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const change = Number(amountPaid) - cartTotal;
  const quickDenominations = [2000, 5000, 10000, 20000, 50000, 100000];

  const handleCheckout = () => {
    if (cart.length === 0) return;
    const transaction: Transaction = {
      id: `TRX-${generateId()}`,
      date: new Date().toISOString(),
      items: [...cart],
      total: cartTotal,
      paymentMethod,
      amountPaid: paymentMethod === PaymentMethod.CASH ? Number(amountPaid) : cartTotal,
      change: paymentMethod === PaymentMethod.CASH ? Math.max(0, change) : 0,
    };
    onCompleteTransaction(transaction);
    setLastTransaction(transaction);
    setCart([]);
    setAmountPaid('');
    setShowCheckoutModal(false);
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-120px)] animate-in slide-in-from-bottom-4 duration-500">
      {/* Product List */}
      <div className="flex-1 flex flex-col gap-6 no-print">
        <div className="flex gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="Cari produk / Tempelkan alat scan..."
              className="w-full pl-12 pr-4 py-4 bg-white rounded-2xl border border-gray-100 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all text-gray-900"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={startScanner}
            className="px-6 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-100 flex items-center gap-2 font-black hover:bg-blue-700 transition-all active:scale-95"
          >
            <Camera size={24} />
            <span className="hidden sm:inline">Scan HP</span>
            <span className="sm:hidden">Scan</span>
          </button>
        </div>

        {/* Notifikasi Scan (Pop-up Kecil) */}
        {scanResult && !showScanner && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[50] animate-in slide-in-from-top-4">
             <div className="bg-blue-600 text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 border border-blue-400">
                <CheckCircle2 size={20} />
                <span className="font-bold text-sm">{scanResult}</span>
             </div>
          </div>
        )}

        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto pb-4 pr-2 custom-scrollbar">
          {filteredProducts.map(product => (
            <button
              key={product.id}
              onClick={() => addToCart(product)}
              disabled={product.stock <= 0}
              className={`flex flex-col bg-white rounded-3xl border border-gray-100 shadow-sm hover:shadow-xl transition-all active:scale-95 text-left group overflow-hidden ${product.stock <= 0 ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              <div className="relative h-32 overflow-hidden bg-gray-50">
                {product.imageUrl ? (
                  <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-gray-300">
                    <ImageIcon size={40} />
                  </div>
                )}
                <div className="absolute top-2 right-2 flex flex-col gap-1 items-end">
                   <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider shadow-sm ${product.stock <= product.minStock ? 'bg-red-500 text-white' : 'bg-white/90 text-gray-800'}`}>
                    SISA: {product.stock}
                  </span>
                  {product.barcode && (
                    <span className="px-2 py-1 bg-gray-900 text-white rounded-md text-[9px] font-black shadow-lg">
                      {product.barcode}
                    </span>
                  )}
                </div>
              </div>
              <div className="p-3 flex-1 flex flex-col">
                <span className="text-[9px] font-bold text-blue-500 uppercase tracking-widest mb-1">{product.category}</span>
                <h4 className="font-bold text-gray-800 text-xs line-clamp-2 mb-2 flex-1 leading-snug">{product.name}</h4>
                <p className="text-blue-600 font-black text-sm">{formatCurrency(product.price)}</p>
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Cart Sidebar */}
      <div className="w-full lg:w-[400px] bg-white rounded-3xl border border-gray-100 shadow-xl flex flex-col no-print">
        <div className="p-6 border-b border-gray-100 flex items-center justify-between">
          <h3 className="text-xl font-bold text-gray-800">Keranjang</h3>
          <span className="px-3 py-1 bg-blue-600 text-white rounded-full text-xs font-black">{cart.length}</span>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-300">
