        </div>
        <div className="p-6 bg-gray-100 border-t border-gray-200 space-y-4">
          <div className="flex justify-between items-center">
            <span className="font-bold text-gray-500 uppercase tracking-widest text-[10px]">Total Bayar</span>
            <span className="text-3xl font-black text-blue-600">{formatCurrency(cartTotal)}</span>
          </div>
          <button onClick={() => setShowCheckoutModal(true)} disabled={cart.length === 0} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl shadow-blue-200 hover:bg-blue-700 active:scale-95 transition-all disabled:opacity-50 uppercase tracking-widest">Lanjut Bayar</button>
        </div>
      </div>

      {/* HP CAMERA SCANNER MODAL (Native) */}
      {showScanner && (
        <div className="fixed inset-0 bg-black z-[2000] flex flex-col items-center justify-center p-4">
          <button onClick={stopScanner} className="absolute top-8 right-8 w-12 h-12 flex items-center justify-center bg-white/20 text-white rounded-full hover:bg-white/30 transition-all z-[2010]"><X size={28} /></button>

          <div className="relative w-full max-w-lg aspect-square md:aspect-video rounded-[3rem] overflow-hidden border-4 border-white/20 shadow-2xl bg-gray-900">
            {isCameraInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center z-20 bg-gray-900">
                <RefreshCw className="w-12 h-12 text-blue-500 animate-spin mb-4" />
                <p className="text-white text-xs font-black uppercase tracking-widest">Membuka Kamera...</p>
              </div>
            )}

            <video ref={videoRef} className="w-full h-full object-cover" playsInline muted />

            {/* Box Overlay kotak biru */}
            <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center">
              <div className="w-72 h-48 border-4 border-blue-500 rounded-3xl relative shadow-[0_0_50px_rgba(59,130,246,0.3)]">
                {/* Garis Animasi Scan */}
                <div className="absolute top-0 left-0 w-full h-1 bg-blue-400 shadow-[0_0_15px_#3b82f6] animate-[scan_2s_infinite]"></div>
