                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => updateQuantity(item.id, -1)} className="w-7 h-7 flex items-center justify-center bg-white text-gray-400 hover:text-red-500 rounded-lg shadow-sm border border-gray-100"><Minus size={14} /></button>
                  <span className="w-5 text-center font-black text-gray-800 text-xs">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.id, 1)} className="w-7 h-7 flex items-center justify-center bg-white text-blue-600 rounded-lg shadow-sm border border-gray-100"><Plus size={14} /></button>
                </div>
              </div>
            ))
          )}
        </div>
        <div className="p-6 bg-gray-100 border-t border-gray-200 space-y-4">
          <div className="flex justify-between items-center">
            <span className="font-bold text-gray-500 uppercase tracking-widest text-[10px]">Total Bayar</span>
            <span className="text-3xl font-black text-blue-600">{formatCurrency(cartTotal)}</span>
          </div>
          <button onClick={() => setShowCheckoutModal(true)} disabled={cart.length === 0} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl shadow-blue-200 hover:bg-blue-700 active:scale-95 transition-all disabled:opacity-50 uppercase tracking-widest">Lanjut Bayar</button>
        </div>
      </div>

      {/* FULL SCREEN CAMERA SCANNER OVERLAY */}
      {showScanner && (
        <div className="fixed inset-0 bg-black z-[2000] flex flex-col items-center justify-center p-4">
          <button onClick={stopScanner} className="absolute top-8 right-8 w-12 h-12 flex items-center justify-center bg-white/20 text-white rounded-full hover:bg-white/30 transition-all z-[2010]"><X size={28} /></button>

          <div className="relative w-full max-w-lg aspect-square rounded-[3rem] overflow-hidden border-4 border-white/20 shadow-2xl bg-gray-900">
            {/* HTML5 QRCODE CONTAINER */}
            <div id="reader" className="w-full h-full"></div>

            {/* UI Overlay (Kotak Biru) */}
