                <div className="absolute top-0 left-0 w-full h-1 bg-blue-400 shadow-[0_0_15px_#3b82f6] animate-[scan_2s_infinite]"></div>
              </div>
              <p className="mt-8 text-white/60 font-black uppercase tracking-widest text-[10px]">Posisikan Barcode Dalam Kotak</p>
