              <div className="absolute inset-x-0 top-10 flex justify-center px-4 animate-in zoom-in-95 z-20">
                <div className={`px-6 py-4 rounded-2xl shadow-2xl border flex items-center gap-3 ${scanResult.includes('OK') ? 'bg-green-600 border-green-400 text-white' : 'bg-red-600 border-red-400 text-white'}`}>
                  {scanResult.includes('OK') ? <CheckCircle2 size={24} /> : <X size={24} />}
                  <span className="font-bold">{scanResult}</span>
                </div>
              </div>
