        <h1 className="text-xl font-bold text-gray-800 tracking-tight">WHY Sembako</h1>
      </div>

      <div className="p-4 border-b border-gray-50 bg-gray-50/50">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-pink-100 flex items-center justify-center text-pink-600 border border-pink-200 shadow-sm">
            <UserIcon size={20} />
          </div>
          <div className="overflow-hidden">
            <p className="text-sm font-bold text-gray-800 truncate">{user.name}</p>
            <p className="text-[10px] font-black uppercase text-pink-500 tracking-wider leading-none mt-0.5">{user.role}</p>
          </div>
        </div>
      </div>

      <nav className="flex-1 p-4 space-y-2 mt-4 overflow-y-auto custom-scrollbar">
        {filteredMenu.map((item) => {
          const Icon = item.icon;
          const isActive = currentView === item.id;
          return (
            <button
              key={item.id}
              type="button"
              onClick={() => setView(item.id as AppView)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 ${
                isActive 
                  ? 'bg-pink-600 text-white font-semibold shadow-md shadow-pink-100' 
                  : 'text-gray-500 hover:bg-gray-50 hover:text-gray-700 font-medium'
              }`}
            >
              <Icon size={20} className={isActive ? 'text-white' : 'text-gray-400'} />
              <span className="text-sm">{item.label}</span>
            </button>
          );
        })}
      </nav>

      <div className="p-4 border-t border-gray-100 space-y-4 bg-white">
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault();
            onLogout();
          }}
          className="w-full flex items-center gap-3 px-4 py-4 rounded-xl text-red-600 bg-red-50 hover:bg-red-600 hover:text-white transition-all duration-200 font-black text-sm group active:scale-[0.95] border border-red-100"
        >
          <LogOut size={18} className="group-hover:rotate-12 transition-transform" />
          <span>Keluar Sistem</span>
        </button>

        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
          <p className="text-[9px] text-gray-400 font-black uppercase tracking-widest mb-2">Sistem Status</p>
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
            <span className="text-[10px] font-bold text-gray-600 uppercase">Aktif & Terenkripsi</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Search, Plus, Minus, Trash2, Banknote, CreditCard, Send, Printer, CheckCircle2, X, ShoppingCart, QrCode, Building2, Wallet, ImageIcon, ScanLine, Camera, Flashlight, List, Loader2, RefreshCw, AlertCircle } from 'lucide-react';
import { Product, CartItem, PaymentMethod, Transaction } from '../types';
import { formatCurrency, generateId } from '../utils';

// Menggunakan global Html5Qrcode dari script tag di index.html
declare const Html5Qrcode: any;

interface CashierProps {
  products: Product[];
  onCompleteTransaction: (transaction: Transaction) => void;
}

const Cashier: React.FC<CashierProps> = ({ products, onCompleteTransaction }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showCheckoutModal, setShowCheckoutModal] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [amountPaid, setAmountPaid] = useState<string>('');
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [scanResult, setScanResult] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [isCameraInitializing, setIsCameraInitializing] = useState(false);

  const scannerRef = useRef<any>(null);
  const lastScannedCode = useRef<string | null>(null);
  const barcodeBuffer = useRef<string>('');
  const lastKeyTime = useRef<number>(0);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const playBeep = () => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = audioCtx.createOscillator();
      const gainNode = audioCtx.createGain();
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.type = 'sine';
      oscillator.frequency.setValueAtTime(880, audioCtx.currentTime);
      gainNode.gain.setValueAtTime(0.1, audioCtx.currentTime);
      oscillator.start();
      oscillator.stop(audioCtx.currentTime + 0.1);
      if ('vibrate' in navigator) navigator.vibrate(100);
    } catch (e) {}
  };

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => 
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    playBeep();
  };

  // DUKUNGAN ALAT SCANNER FISIK (HARDWARE)
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (document.activeElement?.tagName === 'INPUT') return;

      const currentTime = Date.now();
      if (currentTime - lastKeyTime.current > 50) {
        barcodeBuffer.current = '';
      }
      lastKeyTime.current = currentTime;

      if (e.key === 'Enter') {
        if (barcodeBuffer.current.length > 2) {
          const found = products.find(p => p.barcode === barcodeBuffer.current);
          if (found) {
            addToCart(found);
            setScanResult({ message: `Scanned: ${found.name}`, type: 'success' });
            setTimeout(() => setScanResult(null), 2000);
          } else {
            setScanResult({ message: `Barcode ${barcodeBuffer.current} tidak dikenal`, type: 'error' });
            setTimeout(() => setScanResult(null), 2000);
          }
          barcodeBuffer.current = '';
        }
      } else if (e.key.length === 1) {
        barcodeBuffer.current += e.key;
      }
    };

    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [products]);

  // LOGIKA SCANNER HP (KAMERA)
  const startScanner = async () => {
    setShowScanner(true);
    setIsCameraInitializing(true);
    setScanResult(null);
    lastScannedCode.current = null;

    // Tunggu modal muncul di DOM
    setTimeout(async () => {
      try {
        const html5QrCode = new Html5Qrcode("reader");
        scannerRef.current = html5QrCode;

        const config = {
          fps: 10,
          qrbox: { width: 250, height: 150 },
          aspectRatio: 1.0
        };

        await html5QrCode.start(
          { facingMode: "environment" },
          config,
          (decodedText: string) => {
            // Berhenti scan sebentar untuk memproses satu item
            if (lastScannedCode.current === decodedText) return;

            lastScannedCode.current = decodedText;
            const found = products.find(p => p.barcode === decodedText);

            if (found) {
              addToCart(found);
              setScanResult({ message: `Ditemukan: ${found.name}`, type: 'success' });
            } else {
              setScanResult({ message: `Produk tidak ada: ${decodedText}`, type: 'error' });
            }

            // Izinkan scan barcode baru setelah 2 detik
            setTimeout(() => {
              lastScannedCode.current = null;
              setScanResult(null);
            }, 2000);
          },
          () => {} // Ignored search frame error
        );
        setIsCameraInitializing(false);
      } catch (err) {
        console.error("Gagal memulai kamera:", err);
        alert("Tidak dapat mengakses kamera. Pastikan Anda memberikan izin dan menggunakan HTTPS/Localhost.");
        stopScanner();
      }
    }, 300);
  };

  const stopScanner = async () => {
    if (scannerRef.current) {
      try {
        await scannerRef.current.stop();
      } catch (e) {}
      scannerRef.current = null;
    }
    setShowScanner(false);
    setIsCameraInitializing(false);
    setScanResult(null);
  };

  useEffect(() => {
    return () => {
      if (scannerRef.current) scannerRef.current.stop().catch(() => {});
    };
  }, []);

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const change = Number(amountPaid) - cartTotal;
  const quickDenominations = [2000, 5000, 10000, 20000, 50000, 100000];

  const handleCheckout = () => {
    if (cart.length === 0) return;
    const transaction: Transaction = {
      id: `TRX-${generateId()}`,
      date: new Date().toISOString(),
      items: [...cart],
      total: cartTotal,
      paymentMethod,
      amountPaid: paymentMethod === PaymentMethod.CASH ? Number(amountPaid) : cartTotal,
      change: paymentMethod === PaymentMethod.CASH ? Math.max(0, change) : 0,
    };
    onCompleteTransaction(transaction);
    setLastTransaction(transaction);
    setCart([]);
    setAmountPaid('');
    setShowCheckoutModal(false);
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-120px)] animate-in slide-in-from-bottom-4 duration-500">
      {/* Product List Section */}
      <div className="flex-1 flex flex-col gap-6 no-print">
        <div className="flex gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="Cari produk atau tempelkan alat scan..."
              className="w-full pl-12 pr-4 py-4 bg-white rounded-2xl border border-gray-100 shadow-sm focus:outline-none focus:ring-2 focus:ring-pink-500 transition-all text-gray-900 font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={startScanner}
            className="px-6 bg-pink-600 text-white rounded-2xl shadow-lg shadow-pink-100 flex items-center gap-2 font-black hover:bg-pink-700 transition-all active:scale-95"
          >
            <Camera size={24} />
            <span className="hidden sm:inline">Scan HP</span>
            <span className="sm:hidden">Scan</span>
          </button>
        </div>

        {/* Notifikasi Scan Terapung */}
        {scanResult && !showScanner && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] animate-in slide-in-from-top-4">
             <div className={`${scanResult.type === 'success' ? 'bg-pink-600' : 'bg-red-600'} text-white px-8 py-4 rounded-full shadow-2xl flex items-center gap-3 border border-white/20`}>
                {scanResult.type === 'success' ? <CheckCircle2 size={24} /> : <AlertCircle size={24} />}
                <span className="font-bold">{scanResult.message}</span>
             </div>
          </div>
        )}

        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto pb-4 pr-2 custom-scrollbar">
          {filteredProducts.map(product => (
            <button
              key={product.id}
              onClick={() => addToCart(product)}
              disabled={product.stock <= 0}
              className={`flex flex-col bg-white rounded-3xl border border-gray-100 shadow-sm hover:shadow-xl transition-all active:scale-95 text-left group overflow-hidden ${product.stock <= 0 ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              <div className="relative h-32 overflow-hidden bg-gray-50">
                {product.imageUrl ? (
                  <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-gray-300">
                    <ImageIcon size={40} />
                  </div>
                )}
                <div className="absolute top-2 right-2 flex flex-col gap-1 items-end">
                   <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider shadow-sm ${product.stock <= product.minStock ? 'bg-red-500 text-white' : 'bg-white/90 text-gray-800'}`}>
                    SISA: {product.stock}
                  </span>
                  {product.barcode && (
                    <span className="px-2 py-1 bg-gray-900 text-white rounded-md text-[9px] font-black shadow-lg">
                      {product.barcode}
                    </span>
                  )}
                </div>
              </div>
              <div className="p-3 flex-1 flex flex-col">
                <span className="text-[9px] font-bold text-pink-500 uppercase tracking-widest mb-1">{product.category}</span>
                <h4 className="font-bold text-gray-800 text-xs line-clamp-2 mb-2 flex-1 leading-snug">{product.name}</h4>
                <p className="text-pink-600 font-black text-sm">{formatCurrency(product.price)}</p>
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Cart Sidebar Section */}
      <div className="w-full lg:w-[400px] bg-white rounded-3xl border border-gray-100 shadow-xl flex flex-col no-print">
        <div className="p-6 border-b border-gray-100 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <ShoppingCart className="text-pink-600" size={24} />
            <h3 className="text-xl font-bold text-gray-800 tracking-tight">Keranjang</h3>
          </div>
          <span className="px-4 py-1.5 bg-pink-600 text-white rounded-full text-xs font-black shadow-lg shadow-pink-100">{cart.length} Item</span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-300 opacity-60">
              <QrCode className="w-16 h-16 mb-4 animate-pulse" />
              <p className="text-sm font-bold text-center px-8">Tempelkan alat scan ke barcode produk untuk memasukkan barang</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex items-center gap-3 p-3 bg-gray-50 rounded-2xl border border-transparent hover:border-pink-100 transition-all">
                <div className="w-10 h-10 rounded-xl bg-white overflow-hidden shadow-sm border border-gray-100 flex-shrink-0">
                  <img src={item.imageUrl} className="w-full h-full object-cover" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-bold text-gray-800 text-xs truncate leading-tight">{item.name}</p>
                  <p className="text-pink-600 text-[10px] font-black">{formatCurrency(item.price)}</p>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => updateQuantity(item.id, -1)} className="w-7 h-7 flex items-center justify-center bg-white text-gray-400 hover:text-red-500 rounded-lg shadow-sm border border-gray-100 active:scale-90"><Minus size={14} /></button>
                  <span className="w-5 text-center font-black text-gray-800 text-xs">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.id, 1)} className="w-7 h-7 flex items-center justify-center bg-white text-pink-600 rounded-lg shadow-sm border border-gray-100 active:scale-90"><Plus size={14} /></button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-gray-100 border-t border-gray-200 space-y-4">
          <div className="flex justify-between items-center">
            <span className="font-bold text-gray-500 uppercase tracking-widest text-[10px]">Total Belanja</span>
            <span className="text-3xl font-black text-pink-600">{formatCurrency(cartTotal)}</span>
          </div>
          <button 
            onClick={() => setShowCheckoutModal(true)} 
            disabled={cart.length === 0} 
            className="w-full py-5 bg-pink-600 text-white rounded-2xl font-black text-xl shadow-xl shadow-pink-200 hover:bg-pink-700 active:scale-95 transition-all disabled:opacity-50 uppercase tracking-widest"
          >
            Lanjut Bayar
          </button>
        </div>
      </div>

      {/* FULL SCREEN MODAL SCANNER HP */}
      {showScanner && (
        <div className="fixed inset-0 bg-black z-[2000] flex flex-col items-center justify-center p-4">
          <button onClick={stopScanner} className="absolute top-8 right-8 w-12 h-12 flex items-center justify-center bg-white/20 text-white rounded-full hover:bg-white/30 transition-all z-[2010] active:scale-90">
            <X size={28} />
          </button>

          <div className="relative w-full max-w-lg aspect-square rounded-[3rem] overflow-hidden border-4 border-white/20 shadow-2xl bg-gray-900">
            {/* CONTAINER UNTUK HTML5 QRCODE */}
            <div id="reader" className="w-full h-full"></div>

            {/* UI OVERLAY (KOTAK PINK & ANIMASI LASER) */}
            <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center z-10">
              <div className="w-72 h-48 border-4 border-pink-500 rounded-3xl relative shadow-[0_0_40px_rgba(236,72,153,0.4)]">
                {/* Garis Animasi Scan */}
                <div className="absolute top-0 left-0 w-full h-1 bg-pink-400 shadow-[0_0_15px_#ec4899] animate-[scan_2s_infinite]"></div>
              </div>
              <p className="mt-8 text-white/80 font-black uppercase tracking-widest text-[10px] bg-black/40 px-4 py-2 rounded-full backdrop-blur-md">Posisikan Barcode Dalam Kotak</p>
            </div>

            {/* Hasil Scan dalam Modal */}
            {scanResult && (
              <div className="absolute inset-x-0 top-10 flex justify-center px-4 animate-in zoom-in-95 z-20">
                <div className={`px-6 py-4 rounded-2xl shadow-2xl border flex items-center gap-3 ${scanResult.type === 'success' ? 'bg-green-600 border-green-400' : 'bg-red-600 border-red-400'} text-white`}>
                  {scanResult.type === 'success' ? <CheckCircle2 size={24} /> : <AlertCircle size={24} />}
                  <span className="font-bold">{scanResult.message}</span>
                </div>
              </div>
            )}

            {isCameraInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center z-30 bg-gray-900">
                <RefreshCw className="w-12 h-12 text-pink-500 animate-spin mb-4" />
                <p className="text-white text-xs font-black uppercase tracking-widest">Inisialisasi Kamera...</p>
              </div>
            )}
          </div>

          <div className="mt-8 text-white/40 text-[10px] font-bold uppercase tracking-[0.3em]">Smart Scanner System</div>

          <style>{`
            @keyframes scan {
              0% { transform: translateY(0); }
              50% { transform: translateY(184px); }
              100% { transform: translateY(0); }
            }
          `}</style>
        </div>
      )}

      {/* Checkout Modal */}
      {showCheckoutModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[3.5rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95">
              <div className="p-8 flex justify-between items-center border-b border-gray-100 bg-gray-50/50">
                <h3 className="text-2xl font-black text-gray-800 tracking-tight">Metode Pembayaran</h3>
                <button onClick={() => setShowCheckoutModal(false)} className="w-10 h-10 flex items-center justify-center bg-white rounded-full text-gray-400 shadow-sm border border-gray-100"><X size={20} /></button>
              </div>
              <div className="p-8 space-y-8">
                <div className="text-center bg-pink-600 py-12 rounded-[2.5rem] shadow-2xl shadow-pink-200">
                  <p className="text-pink-100 font-bold uppercase tracking-widest text-[10px] mb-2">Total Tagihan</p>
                  <p className="text-6xl font-black text-white">{formatCurrency(cartTotal)}</p>
                </div>
                <div className="space-y-4">
                  <div className="flex gap-2">
                    {Object.values(PaymentMethod).map(method => (
                      <button 
                        key={method} 
                        onClick={() => { setPaymentMethod(method); setAmountPaid(''); }}
                        className={`flex-1 py-4 rounded-2xl font-black text-[10px] uppercase tracking-wider border-2 transition-all ${paymentMethod === method ? 'bg-pink-600 border-pink-600 text-white shadow-lg' : 'bg-white border-gray-100 text-gray-400 hover:border-pink-200'}`}
                      >
                        {method}
                      </button>
                    ))}
                  </div>
                  {paymentMethod === PaymentMethod.CASH && (
                    <div className="space-y-4 animate-in slide-in-from-top-4">
                      <div className="relative">
                        <span className="absolute left-6 top-1/2 -translate-y-1/2 font-black text-gray-300 text-2xl">Rp</span>
                        <input 
                          type="number" 
                          placeholder="Uang yang diterima..." 
                          className="w-full p-6 pl-16 bg-gray-50 border-2 border-gray-100 rounded-[2rem] font-black text-4xl text-right focus:border-pink-500 focus:bg-white focus:outline-none transition-all"
                          value={amountPaid}
                          onChange={(e) => setAmountPaid(e.target.value)}
                          autoFocus
                        />
                      </div>
                      <div className="grid grid-cols-3 gap-2">
                        {quickDenominations.map(d => (
                          <button key={d} onClick={() => setAmountPaid(d.toString())} className="py-4 bg-gray-50 rounded-2xl text-[10px] font-black hover:bg-pink-50 hover:text-pink-600 transition-all border border-transparent hover:border-pink-100">+{d/1000}rb</button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
                <button 
                  onClick={handleCheckout} 
                  disabled={paymentMethod === PaymentMethod.CASH && (!amountPaid || Number(amountPaid) < cartTotal)}
                  className="w-full py-6 bg-pink-600 text-white rounded-[2rem] font-black text-2xl shadow-2xl shadow-pink-200 hover:bg-pink-700 active:scale-95 transition-all disabled:opacity-50"
                >
                  KONFIRMASI PEMBAYARAN
                </button>
              </div>
           </div>
        </div>
      )}

      {/* Success Transaction View */}
      {lastTransaction && !showCheckoutModal && (
        <div className="fixed inset-0 bg-white z-[120] flex flex-col items-center justify-center p-8 text-center animate-in fade-in zoom-in-110 duration-500">
          <div className="w-32 h-32 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-8 animate-bounce shadow-2xl shadow-green-100">
             <CheckCircle2 size={72} />
          </div>
          <h2 className="text-5xl font-black text-gray-800 mb-4 tracking-tighter">Pembayaran Berhasil!</h2>
          <div className="bg-gray-50 px-10 py-6 rounded-3xl border border-gray-100 mb-12">
            <p className="text-gray-400 font-bold uppercase tracking-[0.2em] text-xs mb-1">Uang Kembalian</p>
            <p className="text-5xl font-black text-green-600">{formatCurrency(lastTransaction.change)}</p>
          </div>
          <div className="flex flex-col sm:flex-row gap-4 w-full max-w-lg">
            <button onClick={() => window.print()} className="flex-1 py-6 border-4 border-pink-600 text-pink-600 rounded-[2.5rem] font-black text-xl hover:bg-pink-50 transition-all flex items-center justify-center gap-3 active:scale-95">
              <Printer size={24} />
              Cetak Struk
            </button>
            <button onClick={() => setLastTransaction(null)} className="flex-1 py-6 bg-pink-600 text-white rounded-[2.5rem] font-black text-xl shadow-2xl shadow-pink-200 hover:bg-pink-700 active:scale-95 transition-all uppercase tracking-widest">Transaksi Baru</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Cashier;

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { TrendingUp, Package, AlertTriangle, DollarSign } from 'lucide-react';
import { Product, Transaction } from '../types';
import { formatCurrency } from '../utils';

interface DashboardProps {
  products: Product[];
  transactions: Transaction[];
}

const Dashboard: React.FC<DashboardProps> = ({ products, transactions }) => {
  const today = new Date().toISOString().split('T')[0];
  const todayTransactions = transactions.filter(t => t.date.startsWith(today));
  const dailyTotal = todayTransactions.reduce((acc, t) => acc + t.total, 0);

  const lowStockItems = products.filter(p => p.stock <= p.minStock);
  const totalStockValue = products.reduce((acc, p) => acc + (p.price * p.stock), 0);

  // Chart Data Preparation
  const categoryStats = products.reduce((acc: any, p) => {
    acc[p.category] = (acc[p.category] || 0) + 1;
    return acc;
  }, {});

  const chartData = Object.keys(categoryStats).map(cat => ({
    name: cat,
    count: categoryStats[cat]
  }));

  const COLORS = ['#db2777', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <header>
        <h2 className="text-2xl font-bold text-gray-800">Ringkasan Toko</h2>
        <p className="text-gray-500">Pantau performa harian Anda di sini.</p>
      </header>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-pink-50 text-pink-600 rounded-xl">
            <DollarSign size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-gray-500">Penjualan Hari Ini</p>
            <p className="text-xl font-bold text-gray-800">{formatCurrency(dailyTotal)}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-green-50 text-green-600 rounded-xl">
            <TrendingUp size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-gray-500">Total Transaksi</p>
            <p className="text-xl font-bold text-gray-800">{todayTransactions.length}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl">
            <Package size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-gray-500">Aset Stok</p>
            <p className="text-xl font-bold text-gray-800">{formatCurrency(totalStockValue)}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-red-50 text-red-600 rounded-xl">
            <AlertTriangle size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-gray-500">Stok Menipis</p>
            <p className="text-xl font-bold text-gray-800">{lowStockItems.length} Item</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Chart */}
        <div className="lg:col-span-2 bg-white p-8 rounded-2xl border border-gray-100 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 mb-6">Distribusi Kategori Produk</h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} />
                <YAxis axisLine={false} tickLine={false} />
                <Tooltip 
                   cursor={{fill: '#f8fafc'}}
                   contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
                />
                <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Low Stock Alerts */}
        <div className="bg-white p-8 rounded-2xl border border-gray-100 shadow-sm flex flex-col">
          <h3 className="text-lg font-bold text-gray-800 mb-6 flex items-center gap-2">
            <AlertTriangle className="text-red-500" size={20} />
            Peringatan Stok
          </h3>
          <div className="flex-1 space-y-4 overflow-y-auto max-h-[300px] pr-2 custom-scrollbar">
            {lowStockItems.length > 0 ? (
              lowStockItems.map(item => (
                <div key={item.id} className="flex items-center justify-between p-4 bg-red-50 rounded-xl border border-red-100">
                  <div>
                    <p className="text-sm font-bold text-gray-800">{item.name}</p>
                    <p className="text-xs text-red-600">Sisa: {item.stock} {item.unit}</p>
                  </div>
                  <div className="text-xs font-semibold px-2 py-1 bg-red-100 text-red-700 rounded-md">
                    Isi Ulang
                  </div>
                </div>
              ))
            ) : (
              <div className="text-center py-10">
                <p className="text-gray-400 text-sm italic">Semua stok aman.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { PackagePlus, Edit2, ArrowUpDown, Filter, Trash2, Search, Plus, Check, ChevronDown, SortAsc, SortDesc, X, AlertTriangle, ImageIcon, ScanLine } from 'lucide-react';
import { Product, UnitType } from '../types';
import { formatCurrency, generateId } from '../utils';

interface InventoryProps {
  products: Product[];
  onAddStock: (id: string, amount: number) => void;
  onUpdateProduct: (product: Product) => void;
  onAddProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
}

type SortOrder = 'asc' | 'desc' | 'none';

const Inventory: React.FC<InventoryProps> = ({ products, onAddStock, onUpdateProduct, onAddProduct, onDeleteProduct }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [quickEditingStockId, setQuickEditingStockId] = useState<string | null>(null);
  const [stockAmount, setStockAmount] = useState<string>('');
  const [selectedCategory, setSelectedCategory] = useState<string>('Semua');
  const [sortOrder, setSortOrder] = useState<SortOrder>('none');
  const [showCategoryMenu, setShowCategoryMenu] = useState(false);
  const [showFormModal, setShowFormModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentProductId, setCurrentProductId] = useState<string | null>(null);
  const [productToDelete, setProductToDelete] = useState<{id: string, name: string} | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    barcode: '',
    price: '',
    category: '',
    stock: '',
    minStock: '',
    unit: UnitType.PCS,
    imageUrl: ''
  });

  const categories = useMemo(() => {
    const cats = Array.from(new Set(products.map(p => p.category)));
    return ['Semua', ...cats];
  }, [products]);

  const processedProducts = useMemo(() => {
    let result = products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm));
      const matchesCategory = selectedCategory === 'Semua' || p.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });

    if (sortOrder === 'asc') {
      result.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sortOrder === 'desc') {
      result.sort((a, b) => b.name.localeCompare(a.name));
    }

    return result;
  }, [products, searchTerm, selectedCategory, sortOrder]);

  const handleQuickStockUpdate = (id: string) => {
    const amt = Number(stockAmount);
    if (!isNaN(amt) && amt !== 0) {
      onAddStock(id, amt);
      setQuickEditingStockId(null);
      setStockAmount('');
    }
  };

  const openAddModal = () => {
    setIsEditing(false);
    setCurrentProductId(null);
    setFormData({
      name: '',
      barcode: '',
      price: '',
      category: '',
      stock: '',
      minStock: '',
      unit: UnitType.PCS,
      imageUrl: ''
    });
    setShowFormModal(true);
  };

  const openEditModal = (product: Product) => {
    setIsEditing(true);
    setCurrentProductId(product.id);
    setFormData({
      name: product.name,
      barcode: product.barcode || '',
      price: product.price.toString(),
      category: product.category,
      stock: product.stock.toString(),
      minStock: product.minStock.toString(),
      unit: product.unit,
      imageUrl: product.imageUrl || ''
    });
    setShowFormModal(true);
  };

  const confirmDelete = () => {
    if (productToDelete) {
      onDeleteProduct(productToDelete.id);
      setProductToDelete(null);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.price || !formData.category) {
      alert("Mohon lengkapi data produk!");
      return;
    }

    const productData: Product = {
      id: isEditing && currentProductId ? currentProductId : generateId(),
      barcode: formData.barcode,
      name: formData.name,
      price: Number(formData.price),
      category: formData.category,
      stock: Number(formData.stock) || 0,
      minStock: Number(formData.minStock) || 0,
      unit: formData.unit as UnitType,
      imageUrl: formData.imageUrl
    };

    if (isEditing) {
      onUpdateProduct(productData);
    } else {
      onAddProduct(productData);
    }

    setShowFormModal(false);
  };

  const toggleSort = () => {
    setSortOrder(prev => {
      if (prev === 'none') return 'asc';
      if (prev === 'asc') return 'desc';
      return 'none';
    });
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-800">Manajemen Stok</h2>
          <p className="text-gray-500 font-medium">Kelola inventori dan ketersediaan barang.</p>
        </div>
        <div className="flex gap-2">
           <button 
             onClick={openAddModal}
             className="flex items-center gap-2 px-6 py-3 bg-pink-600 text-white rounded-2xl font-black shadow-lg shadow-pink-100 hover:bg-pink-700 transition-all active:scale-95"
           >
             <PackagePlus size={20} />
             Tambah Produk Baru
           </button>
        </div>
      </header>

      <div className="bg-white rounded-[2rem] border border-gray-100 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex flex-col md:flex-row gap-4 items-center justify-between bg-gray-50/30">
          <div className="relative w-full md:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Cari nama atau barcode..."
              className="w-full pl-11 pr-4 py-3 bg-white border border-transparent rounded-xl shadow-sm focus:ring-2 focus:ring-pink-100 focus:outline-none transition-all text-gray-900 font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex gap-2 relative w-full md:w-auto">
            <button 
              onClick={() => setShowCategoryMenu(!showCategoryMenu)}
              className={`flex-1 md:flex-none flex items-center justify-between gap-3 px-5 py-3 rounded-xl transition-all border ${
                selectedCategory !== 'Semua' 
                  ? 'bg-pink-600 border-pink-600 text-white font-bold' 
                  : 'bg-white border-gray-100 text-gray-500 hover:border-pink-200'
              }`}
            >
              <div className="flex items-center gap-2">
                <Filter size={18} />
                <span className="text-sm uppercase tracking-wider">{selectedCategory}</span>
              </div>
              <ChevronDown size={14} className={`transition-transform duration-200 ${showCategoryMenu ? 'rotate-180' : ''}`} />
            </button>

            {showCategoryMenu && (
              <>
                <div className="fixed inset-0 z-10" onClick={() => setShowCategoryMenu(false)}></div>
                <div className="absolute right-0 mt-14 w-56 bg-white border border-gray-100 rounded-2xl shadow-2xl z-20 py-2 animate-in fade-in zoom-in-95 duration-200">
                  <p className="px-4 py-2 text-[10px] font-black text-gray-400 uppercase tracking-widest border-b border-gray-50 mb-1">Pilih Kategori</p>
                  {categories.map(cat => (
                    <button
                      key={cat}
                      onClick={() => {
                        setSelectedCategory(cat);
                        setShowCategoryMenu(false);
                      }}
                      className="w-full flex items-center justify-between px-4 py-3 text-sm font-bold text-gray-700 hover:bg-pink-50 hover:text-pink-600 transition-colors"
                    >
                      {cat}
                      {selectedCategory === cat && <Check size={16} />}
                    </button>
                  ))}
                </div>
              </>
            )}

            <button 
              onClick={toggleSort}
              className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-5 py-3 rounded-xl transition-all border bg-white border-gray-100 text-gray-500 hover:border-pink-200 font-bold`}
            >
              {sortOrder === 'desc' ? <SortDesc size={18} /> : (sortOrder === 'asc' ? <SortAsc size={18} /> : <ArrowUpDown size={18} />)}
              <span className="text-sm uppercase tracking-wider">Sort</span>
            </button>
          </div>
        </div>

        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white text-gray-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <th className="px-8 py-5 border-b border-gray-100">Info Produk</th>
                <th className="px-8 py-5 border-b border-gray-100">Barcode</th>
                <th className="px-8 py-5 border-b border-gray-100">Harga Jual</th>
                <th className="px-8 py-5 border-b border-gray-100">Stok</th>
                <th className="px-8 py-5 border-b border-gray-100">Status</th>
                <th className="px-8 py-5 border-b border-gray-100 text-center">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {processedProducts.length > 0 ? (
                processedProducts.map(product => (
                  <tr key={product.id} className="hover:bg-pink-50/20 transition-colors group animate-in slide-in-from-left-2 duration-300">
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-14 h-14 bg-gray-50 rounded-2xl border border-gray-100 overflow-hidden shadow-sm flex-shrink-0">
                          {product.imageUrl ? (
                            <img src={product.imageUrl} className="w-full h-full object-cover" />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center text-gray-300">
                              <ImageIcon size={24} />
                            </div>
                          )}
                        </div>
                        <div>
                          <span className="font-black text-gray-800 block leading-tight">{product.name}</span>
                          <span className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">{product.category}</span>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                       <div className="flex items-center gap-2 text-gray-500">
                          <ScanLine size={14} className="text-pink-500" />
                          <span className="font-mono text-xs font-bold">{product.barcode || '-'}</span>
                       </div>
                    </td>
                    <td className="px-8 py-6">
                      <span className="font-black text-gray-900">{formatCurrency(product.price)}</span>
                    </td>
                    <td className="px-8 py-6">
                      {quickEditingStockId === product.id ? (
                        <div className="flex items-center gap-2">
                          <input 
                             type="number"
                             className="w-20 p-2 border-2 border-pink-100 rounded-xl focus:outline-none focus:border-pink-500 text-gray-900 font-black text-center"
                             placeholder="+/-"
                             value={stockAmount}
                             onChange={(e) => setStockAmount(e.target.value)}
                             autoFocus
                          />
                          <button 
                            onClick={() => handleQuickStockUpdate(product.id)}
                            className="w-9 h-9 flex items-center justify-center bg-pink-600 text-white rounded-xl hover:bg-pink-700 transition-colors shadow-lg shadow-pink-100"
                          >
                            <Check size={18} />
                          </button>
                        </div>
                      ) : (
                        <div className="flex items-center gap-2">
                          <span className={`font-black text-lg ${product.stock <= product.minStock ? 'text-red-600' : 'text-gray-800'}`}>
                            {product.stock}
                          </span>
                          <span className="text-[10px] font-bold text-gray-400 uppercase">{product.unit}</span>
                          <button 
                             onClick={() => setQuickEditingStockId(product.id)}
                             className="opacity-0 group-hover:opacity-100 w-8 h-8 flex items-center justify-center text-pink-500 bg-pink-50 rounded-lg transition-all active:scale-90"
                             title="Update Stok"
                          >
                            <Plus size={16} />
                          </button>
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-6">
                      {product.stock <= product.minStock ? (
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-red-50 text-red-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-red-100 w-fit">
                          <AlertTriangle size={12} />
                          Low Stock
                        </div>
                      ) : (
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-green-50 text-green-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-green-100 w-fit">
                          <Check size={12} />
                          Aman
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center justify-center gap-3">
                        <button 
                          onClick={() => openEditModal(product)}
                          className="w-10 h-10 flex items-center justify-center text-gray-400 hover:text-pink-600 hover:bg-pink-50 rounded-xl transition-all active:scale-90 border border-transparent hover:border-pink-100"
                        >
                          <Edit2 size={18} />
                        </button>
                        <button 
                          onClick={() => setProductToDelete({id: product.id, name: product.name})}
                          className="w-10 h-10 flex items-center justify-center text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all active:scale-90 border border-transparent hover:border-pink-100"
                        >
                          <Trash2 size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={6} className="px-8 py-32 text-center">
                    <div className="flex flex-col items-center justify-center text-gray-300">
                      <Search size={64} className="mb-4 opacity-10" />
                      <p className="font-bold text-lg">Produk tidak ditemukan</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showFormModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">
            <div className="p-8 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
              <h3 className="text-2xl font-black text-gray-800 tracking-tight">
                {isEditing ? 'Detail Produk' : 'Produk Baru'}
              </h3>
              <button onClick={() => setShowFormModal(false)} className="w-10 h-10 flex items-center justify-center bg-white rounded-full text-gray-400 hover:text-gray-600 transition-all shadow-sm">
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-10 space-y-8 overflow-y-auto custom-scrollbar">
