      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const playBeep = () => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = audioCtx.createOscillator();
      const gainNode = audioCtx.createGain();
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.type = 'sine';
      oscillator.frequency.setValueAtTime(880, audioCtx.currentTime);
      gainNode.gain.setValueAtTime(0.1, audioCtx.currentTime);
      oscillator.start();
      oscillator.stop(audioCtx.currentTime + 0.1);
      if ('vibrate' in navigator) navigator.vibrate(100);
    } catch (e) {}
  };

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => 
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    playBeep();
  };

  // DUKUNGAN ALAT SCANNER FISIK (HARDWARE)
  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
      if (document.activeElement?.tagName === 'INPUT') return;

      const currentTime = Date.now();
      if (currentTime - lastKeyTime.current > 50) {
        barcodeBuffer.current = '';
      }
      lastKeyTime.current = currentTime;

      if (e.key === 'Enter') {
        if (barcodeBuffer.current.length > 2) {
          const found = products.find(p => p.barcode === barcodeBuffer.current);
          if (found) {
            addToCart(found);
            setScanResult({ message: `Scanned: ${found.name}`, type: 'success' });
            setTimeout(() => setScanResult(null), 2000);
          } else {
            setScanResult({ message: `Barcode ${barcodeBuffer.current} tidak dikenal`, type: 'error' });
            setTimeout(() => setScanResult(null), 2000);
          }
          barcodeBuffer.current = '';
        }
      } else if (e.key.length === 1) {
        barcodeBuffer.current += e.key;
      }
    };

    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [products]);

  // LOGIKA SCANNER HP (KAMERA)
  const startScanner = async () => {
    setShowScanner(true);
    setIsCameraInitializing(true);
    setScanResult(null);
    lastScannedCode.current = null;

    // Tunggu modal muncul di DOM
    setTimeout(async () => {
      try {
        const html5QrCode = new Html5Qrcode("reader");
        scannerRef.current = html5QrCode;

        const config = {
          fps: 10,
          qrbox: { width: 250, height: 150 },
          aspectRatio: 1.0
        };

        await html5QrCode.start(
          { facingMode: "environment" },
          config,
          (decodedText: string) => {
            if (lastScannedCode.current === decodedText) return;

            lastScannedCode.current = decodedText;
            const found = products.find(p => p.barcode === decodedText);

            if (found) {
              addToCart(found);
              setScanResult({ message: `Ditemukan: ${found.name}`, type: 'success' });
            } else {
              setScanResult({ message: `Produk tidak ada: ${decodedText}`, type: 'error' });
            }

            setTimeout(() => {
              lastScannedCode.current = null;
              setScanResult(null);
            }, 2000);
          },
          () => {}
        );
        setIsCameraInitializing(false);
      } catch (err) {
        console.error("Gagal memulai kamera:", err);
        alert("Tidak dapat mengakses kamera. Pastikan Anda memberikan izin dan menggunakan HTTPS/Localhost.");
        stopScanner();
      }
    }, 300);
  };

  const stopScanner = async () => {
    if (scannerRef.current) {
      try {
        await scannerRef.current.stop();
      } catch (e) {}
      scannerRef.current = null;
    }
    setShowScanner(false);
    setIsCameraInitializing(false);
    setScanResult(null);
  };

  useEffect(() => {
    return () => {
      if (scannerRef.current) scannerRef.current.stop().catch(() => {});
    };
  }, []);

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const change = Number(amountPaid) - cartTotal;
  const quickDenominations = [2000, 5000, 10000, 20000, 50000, 100000];

  const handleCheckout = () => {
    if (cart.length === 0) return;
    const transaction: Transaction = {
      id: `TRX-${generateId()}`,
      date: new Date().toISOString(),
      items: [...cart],
      total: cartTotal,
      paymentMethod,
      amountPaid: paymentMethod === PaymentMethod.CASH ? Number(amountPaid) : cartTotal,
      change: paymentMethod === PaymentMethod.CASH ? Math.max(0, change) : 0,
    };
    onCompleteTransaction(transaction);
    setLastTransaction(transaction);
    setCart([]);
    setAmountPaid('');
    setShowCheckoutModal(false);
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-120px)] animate-in slide-in-from-bottom-4 duration-500">
      {/* Product List Section */}
      <div className="flex-1 flex flex-col gap-6 no-print">
        <div className="flex gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="Cari produk atau tempelkan alat scan..."
              className="w-full pl-12 pr-4 py-4 bg-white rounded-2xl border border-gray-100 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all text-gray-900 font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={startScanner}
            className="px-6 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-100 flex items-center gap-2 font-black hover:bg-blue-700 transition-all active:scale-95"
          >
            <Camera size={24} />
            <span className="hidden sm:inline">Scan HP</span>
            <span className="sm:hidden">Scan</span>
          </button>
        </div>

        {/* Notifikasi Scan Terapung */}
        {scanResult && !showScanner && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] animate-in slide-in-from-top-4">
             <div className={`${scanResult.type === 'success' ? 'bg-blue-600' : 'bg-red-600'} text-white px-8 py-4 rounded-full shadow-2xl flex items-center gap-3 border border-white/20`}>
                {scanResult.type === 'success' ? <CheckCircle2 size={24} /> : <AlertCircle size={24} />}
                <span className="font-bold">{scanResult.message}</span>
             </div>
          </div>
        )}

        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto pb-4 pr-2 custom-scrollbar">
          {filteredProducts.map(product => (
            <button
              key={product.id}
              onClick={() => addToCart(product)}
              disabled={product.stock <= 0}
              className={`flex flex-col bg-white rounded-3xl border border-gray-100 shadow-sm hover:shadow-xl transition-all active:scale-95 text-left group overflow-hidden ${product.stock <= 0 ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              <div className="relative h-32 overflow-hidden bg-gray-50">
                {product.imageUrl ? (
                  <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-gray-300">
                    <ImageIcon size={40} />
                  </div>
                )}
                <div className="absolute top-2 right-2 flex flex-col gap-1 items-end">
                   <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider shadow-sm ${product.stock <= product.minStock ? 'bg-red-500 text-white' : 'bg-white/90 text-gray-800'}`}>
                    SISA: {product.stock}
                  </span>
                  {product.barcode && (
                    <span className="px-2 py-1 bg-gray-900 text-white rounded-md text-[9px] font-black shadow-lg">
                      {product.barcode}
                    </span>
                  )}
                </div>
              </div>
              <div className="p-3 flex-1 flex flex-col">
                <span className="text-[9px] font-bold text-blue-500 uppercase tracking-widest mb-1">{product.category}</span>
                <h4 className="font-bold text-gray-800 text-xs line-clamp-2 mb-2 flex-1 leading-snug">{product.name}</h4>
                <p className="text-blue-600 font-black text-sm">{formatCurrency(product.price)}</p>
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Cart Sidebar Section */}
      <div className="w-full lg:w-[400px] bg-white rounded-3xl border border-gray-100 shadow-xl flex flex-col no-print">
        <div className="p-6 border-b border-gray-100 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <ShoppingCart className="text-blue-600" size={24} />
            <h3 className="text-xl font-bold text-gray-800 tracking-tight">Keranjang</h3>
          </div>
          <span className="px-4 py-1.5 bg-blue-600 text-white rounded-full text-xs font-black shadow-lg shadow-blue-100">{cart.length} Item</span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-300 opacity-60">
              <QrCode className="w-16 h-16 mb-4 animate-pulse" />
              <p className="text-sm font-bold text-center px-8">Tempelkan alat scan ke barcode produk untuk memasukkan barang</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex items-center gap-3 p-3 bg-gray-50 rounded-2xl border border-transparent hover:border-blue-100 transition-all">
                <div className="w-10 h-10 rounded-xl bg-white overflow-hidden shadow-sm border border-gray-100 flex-shrink-0">
                  <img src={item.imageUrl} className="w-full h-full object-cover" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-bold text-gray-800 text-xs truncate leading-tight">{item.name}</p>
                  <p className="text-blue-600 text-[10px] font-black">{formatCurrency(item.price)}</p>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => updateQuantity(item.id, -1)} className="w-7 h-7 flex items-center justify-center bg-white text-gray-400 hover:text-red-500 rounded-lg shadow-sm border border-gray-100 active:scale-90"><Minus size={14} /></button>
                  <span className="w-5 text-center font-black text-gray-800 text-xs">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.id, 1)} className="w-7 h-7 flex items-center justify-center bg-white text-blue-600 rounded-lg shadow-sm border border-gray-100 active:scale-90"><Plus size={14} /></button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-gray-100 border-t border-gray-200 space-y-4">
          <div className="flex justify-between items-center">
            <span className="font-bold text-gray-500 uppercase tracking-widest text-[10px]">Total Belanja</span>
            <span className="text-3xl font-black text-blue-600">{formatCurrency(cartTotal)}</span>
          </div>
          <button 
            onClick={() => setShowCheckoutModal(true)} 
            disabled={cart.length === 0} 
            className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl shadow-blue-200 hover:bg-blue-700 active:scale-95 transition-all disabled:opacity-50 uppercase tracking-widest"
          >
            Lanjut Bayar
          </button>
        </div>
      </div>

      {/* FULL SCREEN MODAL SCANNER HP */}
      {showScanner && (
        <div className="fixed inset-0 bg-black z-[2000] flex flex-col items-center justify-center p-4">
          <button onClick={stopScanner} className="absolute top-8 right-8 w-12 h-12 flex items-center justify-center bg-white/20 text-white rounded-full hover:bg-white/30 transition-all z-[2010] active:scale-90">
            <X size={28} />
          </button>

          <div className="relative w-full max-w-lg aspect-square rounded-[3rem] overflow-hidden border-4 border-white/20 shadow-2xl bg-gray-900">
            <div id="reader" className="w-full h-full"></div>

            <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center z-10">
              <div className="w-72 h-48 border-4 border-blue-500 rounded-3xl relative shadow-[0_0_40px_rgba(59,130,246,0.4)]">
                <div className="absolute top-0 left-0 w-full h-1 bg-blue-400 shadow-[0_0_15px_#3b82f6] animate-[scan_2s_infinite]"></div>
              </div>
              <p className="mt-8 text-white/80 font-black uppercase tracking-widest text-[10px] bg-black/40 px-4 py-2 rounded-full backdrop-blur-md">Posisikan Barcode Dalam Kotak</p>
            </div>

            {scanResult && (
              <div className="absolute inset-x-0 top-10 flex justify-center px-4 animate-in zoom-in-95 z-20">
                <div className={`px-6 py-4 rounded-2xl shadow-2xl border flex items-center gap-3 ${scanResult.type === 'success' ? 'bg-green-600 border-green-400' : 'bg-red-600 border-red-400'} text-white`}>
                  {scanResult.type === 'success' ? <CheckCircle2 size={24} /> : <AlertCircle size={24} />}
                  <span className="font-bold">{scanResult.message}</span>
                </div>
              </div>
            )}

            {isCameraInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center z-30 bg-gray-900">
                <RefreshCw className="w-12 h-12 text-blue-500 animate-spin mb-4" />
                <p className="text-white text-xs font-black uppercase tracking-widest">Inisialisasi Kamera...</p>
              </div>
            )}
          </div>

          <div className="mt-8 text-white/40 text-[10px] font-bold uppercase tracking-[0.3em]">Smart Scanner System</div>

          <style>{`
            @keyframes scan {
              0% { transform: translateY(0); }
              50% { transform: translateY(184px); }
              100% { transform: translateY(0); }
            }
          `}</style>
        </div>
      )}

      {/* Checkout Modal */}
      {showCheckoutModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[3.5rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95">
              <div className="p-8 flex justify-between items-center border-b border-gray-100 bg-gray-50/50">
                <h3 className="text-2xl font-black text-gray-800 tracking-tight">Metode Pembayaran</h3>
                <button onClick={() => setShowCheckoutModal(false)} className="w-10 h-10 flex items-center justify-center bg-white rounded-full text-gray-400 shadow-sm border border-gray-100"><X size={20} /></button>
              </div>
              <div className="p-8 space-y-8">
                <div className="text-center bg-blue-600 py-12 rounded-[2.5rem] shadow-2xl shadow-blue-200">
                  <p className="text-blue-100 font-bold uppercase tracking-widest text-[10px] mb-2">Total Tagihan</p>
                  <p className="text-6xl font-black text-white">{formatCurrency(cartTotal)}</p>
                </div>
                <div className="space-y-4">
                  <div className="flex gap-2">
                    {Object.values(PaymentMethod).map(method => (
                      <button 
                        key={method} 
                        onClick={() => { setPaymentMethod(method); setAmountPaid(''); }}
                        className={`flex-1 py-4 rounded-2xl font-black text-[10px] uppercase tracking-wider border-2 transition-all ${paymentMethod === method ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-white border-gray-100 text-gray-400 hover:border-blue-200'}`}
                      >
                        {method}
                      </button>
                    ))}
                  </div>
                  {paymentMethod === PaymentMethod.CASH && (
                    <div className="space-y-4 animate-in slide-in-from-top-4">
                      <div className="relative">
                        <span className="absolute left-6 top-1/2 -translate-y-1/2 font-black text-gray-300 text-2xl">Rp</span>
                        <input 
                          type="number" 
                          placeholder="Uang yang diterima..." 
                          className="w-full p-6 pl-16 bg-gray-50 border-2 border-gray-100 rounded-[2rem] font-black text-4xl text-right focus:border-blue-500 focus:bg-white focus:outline-none transition-all"
                          value={amountPaid}
                          onChange={(e) => setAmountPaid(e.target.value)}
                          autoFocus
                        />
                      </div>
                      <div className="grid grid-cols-3 gap-2">
                        {quickDenominations.map(d => (
                          <button key={d} onClick={() => setAmountPaid(d.toString())} className="py-4 bg-gray-50 rounded-2xl text-[10px] font-black hover:bg-blue-50 hover:text-blue-600 transition-all border border-transparent hover:border-blue-100">+{d/1000}rb</button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
                <button 
                  onClick={handleCheckout} 
                  disabled={paymentMethod === PaymentMethod.CASH && (!amountPaid || Number(amountPaid) < cartTotal)}
                  className="w-full py-6 bg-blue-600 text-white rounded-[2rem] font-black text-2xl shadow-2xl shadow-blue-200 hover:bg-blue-700 active:scale-95 transition-all disabled:opacity-50"
                >
                  KONFIRMASI PEMBAYARAN
                </button>
              </div>
           </div>
        </div>
      )}

      {/* Success Transaction View */}
      {lastTransaction && !showCheckoutModal && (
        <div className="fixed inset-0 bg-white z-[120] flex flex-col items-center justify-center p-8 text-center animate-in fade-in zoom-in-110 duration-500">
          <div className="w-32 h-32 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-8 animate-bounce shadow-2xl shadow-green-100">
             <CheckCircle2 size={72} />
          </div>
          <h2 className="text-5xl font-black text-gray-800 mb-4 tracking-tighter">Pembayaran Berhasil!</h2>
          <div className="bg-gray-50 px-10 py-6 rounded-3xl border border-gray-100 mb-12">
            <p className="text-gray-400 font-bold uppercase tracking-[0.2em] text-xs mb-1">Uang Kembalian</p>
            <p className="text-5xl font-black text-green-600">{formatCurrency(lastTransaction.change)}</p>
          </div>
          <div className="flex flex-col sm:flex-row gap-4 w-full max-w-lg">
            <button onClick={() => window.print()} className="flex-1 py-6 border-4 border-blue-600 text-blue-600 rounded-[2.5rem] font-black text-xl hover:bg-blue-50 transition-all flex items-center justify-center gap-3 active:scale-95">
              <Printer size={24} />
              Cetak Struk
            </button>
            <button onClick={() => setLastTransaction(null)} className="flex-1 py-6 bg-blue-600 text-white rounded-[2.5rem] font-black text-xl shadow-2xl shadow-blue-200 hover:bg-blue-700 active:scale-95 transition-all uppercase tracking-widest">Transaksi Baru</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Cashier;

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { TrendingUp, Package, AlertTriangle, DollarSign } from 'lucide-react';
import { Product, Transaction } from '../types';
import { formatCurrency } from '../utils';

interface DashboardProps {
  products: Product[];
  transactions: Transaction[];
}

const Dashboard: React.FC<DashboardProps> = ({ products, transactions }) => {
  const today = new Date().toISOString().split('T')[0];
  const todayTransactions = transactions.filter(t => t.date.startsWith(today));
  const dailyTotal = todayTransactions.reduce((acc, t) => acc + t.total, 0);

  const lowStockItems = products.filter(p => p.stock <= p.minStock);
  const totalStockValue = products.reduce((acc, p) => acc + (p.price * p.stock), 0);

  const categoryStats = products.reduce((acc: any, p) => {
    acc[p.category] = (acc[p.category] || 0) + 1;
    return acc;
  }, {});

  const chartData = Object.keys(categoryStats).map(cat => ({
    name: cat,
    count: categoryStats[cat]
  }));

  const COLORS = ['#2563eb', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <header>
        <h2 className="text-2xl font-bold text-gray-800">Ringkasan Toko</h2>
        <p className="text-gray-500">Pantau performa harian Anda di sini.</p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-xl">
            <DollarSign size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-gray-500">Penjualan Hari Ini</p>
            <p className="text-xl font-bold text-gray-800">{formatCurrency(dailyTotal)}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-green-50 text-green-600 rounded-xl">
            <TrendingUp size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-gray-500">Total Transaksi</p>
            <p className="text-xl font-bold text-gray-800">{todayTransactions.length}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-purple-50 text-purple-600 rounded-xl">
            <Package size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-gray-500">Aset Stok</p>
            <p className="text-xl font-bold text-gray-800">{formatCurrency(totalStockValue)}</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-red-50 text-red-600 rounded-xl">
            <AlertTriangle size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-gray-500">Stok Menipis</p>
            <p className="text-xl font-bold text-gray-800">{lowStockItems.length} Item</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-2xl border border-gray-100 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 mb-6">Distribusi Kategori Produk</h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} />
                <YAxis axisLine={false} tickLine={false} />
                <Tooltip 
                   cursor={{fill: '#f8fafc'}}
                   contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
                />
                <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-2xl border border-gray-100 shadow-sm flex flex-col">
          <h3 className="text-lg font-bold text-gray-800 mb-6 flex items-center gap-2">
            <AlertTriangle className="text-red-500" size={20} />
            Peringatan Stok
          </h3>
          <div className="flex-1 space-y-4 overflow-y-auto max-h-[300px] pr-2 custom-scrollbar">
            {lowStockItems.length > 0 ? (
              lowStockItems.map(item => (
                <div key={item.id} className="flex items-center justify-between p-4 bg-red-50 rounded-xl border border-red-100">
                  <div>
                    <p className="text-sm font-bold text-gray-800">{item.name}</p>
                    <p className="text-xs text-red-600">Sisa: {item.stock} {item.unit}</p>
                  </div>
                  <div className="text-xs font-semibold px-2 py-1 bg-red-100 text-red-700 rounded-md">
                    Isi Ulang
                  </div>
                </div>
              ))
            ) : (
              <div className="text-center py-10">
                <p className="text-gray-400 text-sm italic">Semua stok aman.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { PackagePlus, Edit2, ArrowUpDown, Filter, Trash2, Search, Plus, Check, ChevronDown, SortAsc, SortDesc, X, AlertTriangle, ImageIcon, ScanLine } from 'lucide-react';
import { Product, UnitType } from '../types';
import { formatCurrency, generateId } from '../utils';

interface InventoryProps {
  products: Product[];
  onAddStock: (id: string, amount: number) => void;
  onUpdateProduct: (product: Product) => void;
  onAddProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
}

type SortOrder = 'asc' | 'desc' | 'none';

const Inventory: React.FC<InventoryProps> = ({ products, onAddStock, onUpdateProduct, onAddProduct, onDeleteProduct }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [quickEditingStockId, setQuickEditingStockId] = useState<string | null>(null);
  const [stockAmount, setStockAmount] = useState<string>('');
  const [selectedCategory, setSelectedCategory] = useState<string>('Semua');
  const [sortOrder, setSortOrder] = useState<SortOrder>('none');
  const [showCategoryMenu, setShowCategoryMenu] = useState(false);
  const [showFormModal, setShowFormModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentProductId, setCurrentProductId] = useState<string | null>(null);
  const [productToDelete, setProductToDelete] = useState<{id: string, name: string} | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    barcode: '',
    price: '',
    category: '',
    stock: '',
    minStock: '',
    unit: UnitType.PCS,
    imageUrl: ''
  });

  const categories = useMemo(() => {
    const cats = Array.from(new Set(products.map(p => p.category)));
    return ['Semua', ...cats];
  }, [products]);

  const processedProducts = useMemo(() => {
    let result = products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm));
      const matchesCategory = selectedCategory === 'Semua' || p.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });

    if (sortOrder === 'asc') {
      result.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sortOrder === 'desc') {
      result.sort((a, b) => b.name.localeCompare(a.name));
    }

    return result;
  }, [products, searchTerm, selectedCategory, sortOrder]);

  const handleQuickStockUpdate = (id: string) => {
    const amt = Number(stockAmount);
    if (!isNaN(amt) && amt !== 0) {
      onAddStock(id, amt);
      setQuickEditingStockId(null);
      setStockAmount('');
    }
  };

  const openAddModal = () => {
    setIsEditing(false);
    setCurrentProductId(null);
    setFormData({
      name: '',
      barcode: '',
      price: '',
      category: '',
      stock: '',
      minStock: '',
      unit: UnitType.PCS,
      imageUrl: ''
    });
    setShowFormModal(true);
  };

  const openEditModal = (product: Product) => {
    setIsEditing(true);
    setCurrentProductId(product.id);
    setFormData({
      name: product.name,
      barcode: product.barcode || '',
      price: product.price.toString(),
      category: product.category,
      stock: product.stock.toString(),
      minStock: product.minStock.toString(),
      unit: product.unit,
      imageUrl: product.imageUrl || ''
    });
    setShowFormModal(true);
  };

  const confirmDelete = () => {
    if (productToDelete) {
      onDeleteProduct(productToDelete.id);
      setProductToDelete(null);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.price || !formData.category) {
      alert("Mohon lengkapi data produk!");
      return;
    }

    const productData: Product = {
      id: isEditing && currentProductId ? currentProductId : generateId(),
      barcode: formData.barcode,
      name: formData.name,
      price: Number(formData.price),
      category: formData.category,
      stock: Number(formData.stock) || 0,
      minStock: Number(formData.minStock) || 0,
      unit: formData.unit as UnitType,
      imageUrl: formData.imageUrl
    };

    if (isEditing) {
      onUpdateProduct(productData);
    } else {
      onAddProduct(productData);
    }

    setShowFormModal(false);
  };

  const toggleSort = () => {
    setSortOrder(prev => {
      if (prev === 'none') return 'asc';
      if (prev === 'asc') return 'desc';
      return 'none';
    });
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-800">Manajemen Stok</h2>
          <p className="text-gray-500 font-medium">Kelola inventori dan ketersediaan barang.</p>
        </div>
        <div className="flex gap-2">
           <button 
             onClick={openAddModal}
             className="flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-2xl font-black shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
           >
             <PackagePlus size={20} />
