                      value={formData.minStock}
                      onChange={(e) => setFormData({...formData, minStock: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setShowFormModal(false)} className="flex-1 py-5 text-gray-400 font-black hover:bg-gray-100 rounded-[2rem] transition-all uppercase tracking-widest text-sm">Batal</button>
                <button type="submit" className="flex-1 py-5 bg-blue-600 text-white font-black rounded-[2rem] shadow-2xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95 uppercase tracking-widest text-sm">
