            {isCameraInitializing && (
              <div className="absolute inset-0 flex flex-col items-center justify-center z-30 bg-gray-900">
                <RefreshCw className="w-12 h-12 text-blue-500 animate-spin mb-4" />
                <p className="text-white text-xs font-black uppercase tracking-widest">Inisialisasi Kamera...</p>
              </div>
            )}
          </div>
        </div>
      )}

      {showCheckoutModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95">
