                  {Number(amountPaid) >= cartTotal && (
                    <div className="p-4 bg-green-50 rounded-2xl flex justify-between items-center border border-green-100">
                      <span className="text-sm font-bold text-green-700">Kembalian:</span>
                      <span className="text-xl font-black text-green-700">{formatCurrency(change)}</span>
                    </div>
                  )}
                </div>
              )}

              {paymentMethod === PaymentMethod.QRIS && (
                <div className="flex flex-col items-center gap-4 py-4 animate-in zoom-in-95">
                  <div className="bg-white p-4 rounded-3xl shadow-lg border-2 border-blue-50">
                    <img 
                      src={`https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=WHY-SEMBAKO-${generateId()}`} 
                      alt="QRIS Demo"
                      className="w-44 h-44"
                    />
                  </div>
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">Silahkan Scan QRIS Diatas</p>
                </div>
              )}

              {paymentMethod === PaymentMethod.TRANSFER && (
                <div className="space-y-4 animate-in slide-in-from-top-4">
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Pilih Bank / E-Wallet:</p>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <p className="text-[9px] font-bold text-blue-600">BANK</p>
                      <div className="grid grid-cols-2 gap-2">
                        {bankOptions.map(bank => (
                          <button 
                            key={bank} 
                            onClick={() => setPaymentProvider(bank)}
                            className={`p-3 rounded-xl text-[10px] font-black border transition-all ${paymentProvider === bank ? 'bg-blue-50 border-blue-500 text-blue-700 shadow-sm' : 'bg-white border-gray-100 text-gray-500'}`}
                          >
                            {bank}
                          </button>
                        ))}
                      </div>
                    </div>
                    <div className="space-y-2">
                      <p className="text-[9px] font-bold text-blue-600">E-WALLET</p>
                      <div className="grid grid-cols-2 gap-2">
                        {ewalletOptions.map(ew => (
                          <button 
                            key={ew} 
                            onClick={() => setPaymentProvider(ew)}
                            className={`p-3 rounded-xl text-[10px] font-black border transition-all ${paymentProvider === ew ? 'bg-blue-50 border-blue-500 text-blue-700 shadow-sm' : 'bg-white border-gray-100 text-gray-500'}`}
                          >
                            {ew}
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              )}

              <button 
                onClick={handleCheckout} 
                disabled={
                  (paymentMethod === PaymentMethod.CASH && (!amountPaid || Number(amountPaid) < cartTotal)) ||
                  (paymentMethod === PaymentMethod.TRANSFER && !paymentProvider)
                }
                className="w-full py-6 bg-blue-600 text-white rounded-[2rem] font-black text-2xl shadow-2xl hover:bg-blue-700 transition-all disabled:opacity-50"
              >
                KONFIRMASI PEMBAYARAN
              </button>
            </div>
          </div>
        </div>
      )}

      {lastTransaction && (
        <div className="fixed inset-0 bg-white z-[200] flex flex-col items-center justify-center p-8 text-center animate-in fade-in zoom-in-110">
          <div className="no-print flex flex-col items-center">
            <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6 animate-bounce">
              <CheckCircle2 size={48} />
            </div>
            <h2 className="text-4xl font-black text-gray-800 mb-2">Transaksi Berhasil!</h2>
            <p className="text-gray-500 mb-8">Silahkan cetak struk atau mulai transaksi baru.</p>

            <div className="flex gap-4 w-full max-w-md">
              <button onClick={handlePrint} className="flex-1 py-5 border-4 border-blue-600 text-blue-600 rounded-[2rem] font-black text-lg hover:bg-blue-50 flex items-center justify-center gap-3">
                <Printer size={24} /> Cetak Struk
              </button>
              <button onClick={() => setLastTransaction(null)} className="flex-1 py-5 bg-blue-600 text-white rounded-[2rem] font-black text-lg shadow-xl hover:bg-blue-700 transition-all">
                Selesai
              </button>
            </div>
          </div>

          <div className="print-only mt-8">
            <Receipt transaction={lastTransaction} />
          </div>
        </div>
      )}

      <style>{`
        @keyframes scan {
          0% { transform: translateY(0); }
          50% { transform: translateY(184px); }
          100% { transform: translateY(0); }
        }
        @media print {
          body * { visibility: hidden; }
          .print-only, .print-only * { visibility: visible; }
          .print-only { position: absolute; left: 0; top: 0; width: 100%; }
        }
      `}</style>
    </div>
  );
};

export default Cashier;

