import React, { useState, useEffect, useCallback } from 'react';
import { AppView, Product, Transaction, User } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Cashier from './components/Cashier';
import Inventory from './components/Inventory';
import History from './components/History';
import Login from './components/Login';
import { INITIAL_PRODUCTS } from './data';
import { CheckCircle2, AlertCircle, X } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('user');
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [currentView, setCurrentView] = useState<AppView>('dashboard');
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('transactions');
    return saved ? JSON.parse(saved) : [];
  });
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    localStorage.setItem('products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    if (user) {
      localStorage.setItem('user', JSON.stringify(user));
    } else {
      localStorage.removeItem('user');
    }
  }, [user]);

  const handleLogin = (userData: User) => {
    setUser(userData);
    setCurrentView(userData.role === 'kasir' ? 'cashier' : 'dashboard');
    showNotification(`Selamat datang, ${userData.name}!`, 'success');
  };

  const handleLogout = () => {
    localStorage.clear();
    setUser(null);
    window.location.href = window.location.origin;
  };

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setNotification({ message, type });
  };

  const handleCompleteTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);
    setProducts(prev => prev.map(p => {
      const soldItem = transaction.items.find(i => i.id === p.id);
      if (soldItem) {
        return { ...p, stock: Math.max(0, p.stock - soldItem.quantity) };
      }
      return p;
    }));
    showNotification('Transaksi Berhasil Disimpan!');
  };

  const handleAddStock = (id: string, amount: number) => {
    setProducts(prev => prev.map(p => {
      if (p.id === id) return { ...p, stock: p.stock + amount };
      return p;
    }));
    showNotification('Stok Berhasil Diperbarui');
  };

  const handleAddProduct = (newProduct: Product) => {
    setProducts(prev => [...prev, newProduct]);
    showNotification('Produk Baru Ditambahkan');
  };

  const handleUpdateProduct = (updatedProduct: Product) => {
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    showNotification('Data Produk Diperbarui');
  };

  const handleDeleteProduct = (id: string) => {
    const productToDelete = products.find(p => p.id === id);
    setProducts(prev => prev.filter(p => p.id !== id));
    showNotification(`Produk "${productToDelete?.name}" Berhasil Dihapus`, 'success');
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  const renderView = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard products={products} transactions={transactions} />;
      case 'cashier':
        return <Cashier products={products} user={user} onCompleteTransaction={handleCompleteTransaction} />;
      case 'inventory':
        return <Inventory products={products} onAddStock={handleAddStock} onUpdateProduct={handleUpdateProduct} onAddProduct={handleAddProduct} onDeleteProduct={handleDeleteProduct} />;
      case 'history':
        return <History transactions={transactions} />;
      default:
        return <Dashboard products={products} transactions={transactions} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] flex">
      <Sidebar currentView={currentView} setView={setCurrentView} user={user} onLogout={handleLogout} />
      <main className="flex-1 ml-64 flex flex-col min-h-screen relative">
        <div className="flex-1 p-8 overflow-y-auto">
          <div className="max-w-7xl mx-auto no-print pb-20">
            {renderView()}
          </div>
        </div>
        <footer className="py-6 px-8 border-t border-gray-100 bg-white no-print mt-auto">
          <div className="max-w-7xl mx-auto flex flex-col items-center justify-center text-gray-400 text-sm space-y-1">
            <p className="font-medium italic">copyright@WHY_Sembako</p>
            <p className="text-[10px] uppercase tracking-[0.2em] font-bold opacity-60">Smart Retail System</p>
          </div>
        </footer>
      </main>

      {notification && (
        <div className="fixed bottom-8 right-8 z-[100] animate-in slide-in-from-right-10 fade-in duration-300">
          <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
            notification.type === 'success' 
              ? 'bg-white border-pink-100 text-pink-700' 
              : 'bg-white border-red-100 text-red-700'
          }`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
            <span className="font-bold text-sm">{notification.message}</span>
            <button onClick={() => setNotification(null)} className="ml-2 opacity-50 hover:opacity-100 transition-opacity">
              <X size={16} />
            </button>
          </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background-color: #fce7f3; border-radius: 20px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background-color: #fbcfe8; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Search, Plus, Minus, Trash2, Banknote, CreditCard, Send, Printer, CheckCircle2, X, ShoppingCart, QrCode, Building2, Wallet, ImageIcon, ScanLine, Camera, Flashlight, List, Loader2, RefreshCw, AlertCircle, Smartphone } from 'lucide-react';
import { Product, CartItem, PaymentMethod, Transaction, User } from '../types';
import { formatCurrency, generateId } from '../utils';
import Receipt from './Receipt';

declare const Html5Qrcode: any;

interface CashierProps {
  products: Product[];
  user?: User | null;
  onCompleteTransaction: (transaction: Transaction) => void;
}

const Cashier: React.FC<CashierProps> = ({ products, user, onCompleteTransaction }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showCheckoutModal, setShowCheckoutModal] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [paymentProvider, setPaymentProvider] = useState<string>('');
  const [amountPaid, setAmountPaid] = useState<string>('');
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [scanResult, setScanResult] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [isCameraInitializing, setIsCameraInitializing] = useState(false);

  const scannerRef = useRef<any>(null);
  const lastScannedCode = useRef<string | null>(null);

  const bankOptions = ['BCA', 'BRI', 'Mandiri', 'SeaBank'];
  const ewalletOptions = ['DANA', 'GoPay', 'OVO', 'ShopeePay'];

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => 
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const startScanner = async () => {
    setShowScanner(true);
    setIsCameraInitializing(true);
    setTimeout(async () => {
      try {
        const html5QrCode = new Html5Qrcode("reader");
        scannerRef.current = html5QrCode;
        await html5QrCode.start(
          { facingMode: "environment" },
          { fps: 10, qrbox: { width: 250, height: 150 }, aspectRatio: 1.0 },
          (decodedText: string) => {
            if (lastScannedCode.current === decodedText) return;
            lastScannedCode.current = decodedText;
            const found = products.find(p => p.barcode === decodedText);
            if (found) {
              addToCart(found);
              setScanResult({ message: `Ditemukan: ${found.name}`, type: 'success' });
            } else {
              setScanResult({ message: `Barcode tidak dikenal: ${decodedText}`, type: 'error' });
            }
            setTimeout(() => { lastScannedCode.current = null; setScanResult(null); }, 2000);
          },
          () => {}
        );
        setIsCameraInitializing(false);
      } catch (err) {
        alert("Gagal mengakses kamera.");
        setShowScanner(false);
      }
    }, 300);
  };

  const stopScanner = async () => {
    if (scannerRef.current) await scannerRef.current.stop().catch(() => {});
    setShowScanner(false);
    setIsCameraInitializing(false);
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) return { ...item, quantity: Math.max(0, item.quantity + delta) };
      return item;
    }).filter(item => item.quantity > 0));
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const change = Number(amountPaid) - cartTotal;
  const quickDenominations = [2000, 5000, 10000, 20000, 50000, 100000];

  const handleCheckout = () => {
    if (cart.length === 0) return;
    const transaction: Transaction = {
      id: `BON${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      items: [...cart],
      total: cartTotal,
      paymentMethod,
      paymentProvider: paymentMethod !== PaymentMethod.CASH ? paymentProvider : 'Tunai',
      amountPaid: paymentMethod === PaymentMethod.CASH ? Number(amountPaid) : cartTotal,
      change: paymentMethod === PaymentMethod.CASH ? Math.max(0, change) : 0,
      cashierName: user?.name || 'Kasir'
    };
    onCompleteTransaction(transaction);
    setLastTransaction(transaction);
    setCart([]);
    setAmountPaid('');
    setPaymentProvider('');
    setShowCheckoutModal(false);
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-120px)] animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex-1 flex flex-col gap-6 no-print">
        <div className="flex gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="Cari produk..."
              className="w-full pl-12 pr-4 py-4 bg-white rounded-2xl border border-gray-100 shadow-sm focus:outline-none focus:ring-2 focus:ring-pink-500 transition-all text-gray-900 font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button onClick={startScanner} className="px-6 bg-pink-600 text-white rounded-2xl shadow-lg flex items-center gap-2 font-black hover:bg-pink-700 transition-all active:scale-95">
            <Camera size={24} />
            <span className="hidden sm:inline">Scan HP</span>
          </button>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto pb-4 pr-2 custom-scrollbar">
          {filteredProducts.map(product => (
            <button key={product.id} onClick={() => addToCart(product)} className="flex flex-col bg-white rounded-3xl border border-gray-100 shadow-sm hover:shadow-xl transition-all text-left overflow-hidden group active:scale-95">
              <div className="relative h-32 overflow-hidden bg-gray-50">
                <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                <div className="absolute top-2 right-2 px-2 py-1 bg-white/90 rounded-lg text-[9px] font-black text-black">STOK: {product.stock}</div>
              </div>
              <div className="p-3">
                <span className="text-[9px] font-bold text-pink-500 uppercase tracking-widest">{product.category}</span>
                <h4 className="font-bold text-gray-800 text-xs line-clamp-2">{product.name}</h4>
                <p className="text-pink-600 font-black text-sm">{formatCurrency(product.price)}</p>
              </div>
            </button>
          ))}
        </div>
      </div>

      <div className="w-full lg:w-[400px] bg-white rounded-3xl border border-gray-100 shadow-xl flex flex-col no-print">
        <div className="p-6 border-b border-gray-100 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <ShoppingCart className="text-pink-600" size={24} />
            <h3 className="text-xl font-bold text-gray-800 tracking-tight">Keranjang</h3>
          </div>
          <span className="px-4 py-1.5 bg-pink-600 text-white rounded-full text-xs font-black shadow-lg shadow-pink-100">{cart.length} Item</span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-300 opacity-60">
              <QrCode className="w-16 h-16 mb-4 animate-pulse" />
              <p className="text-sm font-bold text-center px-8">Belum ada barang dipilih</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex items-center gap-3 p-3 bg-gray-50 rounded-2xl border border-transparent hover:border-pink-100 transition-all">
                <div className="w-10 h-10 rounded-xl bg-white overflow-hidden shadow-sm border border-gray-100 flex-shrink-0">
                  <img src={item.imageUrl} className="w-full h-full object-cover" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-bold text-gray-800 text-xs truncate leading-tight">{item.name}</p>
                  <p className="text-pink-600 text-[10px] font-black">{formatCurrency(item.price)}</p>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => updateQuantity(item.id, -1)} className="w-7 h-7 flex items-center justify-center bg-white text-gray-400 rounded-lg shadow-sm border border-gray-100 active:scale-90"><Minus size={14} /></button>
                  <span className="w-5 text-center font-black text-gray-800 text-xs">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.id, 1)} className="w-7 h-7 flex items-center justify-center bg-white text-pink-600 rounded-lg shadow-sm border border-gray-100 active:scale-90"><Plus size={14} /></button>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-gray-100 border-t border-gray-200 space-y-4">
          <div className="flex justify-between items-center">
            <span className="font-bold text-gray-500 uppercase tracking-widest text-[10px]">Total Belanja</span>
            <span className="text-3xl font-black text-pink-600">{formatCurrency(cartTotal)}</span>
          </div>
          <button 
            onClick={() => { setShowCheckoutModal(true); setPaymentMethod(PaymentMethod.CASH); }} 
            disabled={cart.length === 0} 
            className="w-full py-5 bg-pink-600 text-white rounded-2xl font-black text-xl shadow-xl shadow-pink-200 hover:bg-pink-700 transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest"
          >
            Lanjut Bayar
          </button>
        </div>
      </div>

      {showScanner && (
        <div className="fixed inset-0 bg-black z-[2000] flex flex-col items-center justify-center p-4">
          <button onClick={stopScanner} className="absolute top-8 right-8 w-12 h-12 flex items-center justify-center bg-white/20 text-white rounded-full hover:bg-white/30 z-[2010]">
            <X size={28} />
          </button>
          <div className="relative w-full max-w-lg aspect-square rounded-[3rem] overflow-hidden border-4 border-white/20 shadow-2xl bg-gray-900">
            <div id="reader" className="w-full h-full"></div>
            <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center z-10">
              <div className="w-72 h-48 border-4 border-pink-500 rounded-3xl relative shadow-[0_0_40px_rgba(236,72,153,0.4)]">
                <div className="absolute top-0 left-0 w-full h-1 bg-pink-400 shadow-[0_0_15px_#ec4899] animate-[scan_2s_infinite]"></div>
              </div>
            </div>
          </div>
        </div>
      )}

      {showCheckoutModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 flex justify-between items-center border-b border-gray-100 bg-gray-50/50">
              <h3 className="text-2xl font-black text-gray-800 tracking-tight">Metode Pembayaran</h3>
              <button onClick={() => setShowCheckoutModal(false)} className="w-10 h-10 flex items-center justify-center bg-white rounded-full text-gray-400 shadow-sm border border-gray-100"><X size={20} /></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="text-center bg-pink-600 py-8 rounded-[2rem] shadow-xl shadow-pink-100">
                <p className="text-pink-100 font-bold uppercase tracking-widest text-[10px] mb-1">Total Tagihan</p>
                <p className="text-5xl font-black text-white">{formatCurrency(cartTotal)}</p>
              </div>

              <div className="grid grid-cols-3 gap-2">
                {Object.values(PaymentMethod).map(method => (
                  <button 
                    key={method} 
                    onClick={() => { setPaymentMethod(method); setPaymentProvider(''); setAmountPaid(''); }}
                    className={`py-4 rounded-xl font-black text-[10px] uppercase tracking-wider border-2 transition-all ${paymentMethod === method ? 'bg-pink-600 border-pink-600 text-white shadow-lg' : 'bg-white border-gray-100 text-gray-400'}`}
                  >
                    {method}
                  </button>
                ))}
              </div>

              {paymentMethod === PaymentMethod.CASH && (
                <div className="space-y-4 animate-in slide-in-from-top-4">
                  <div className="relative">
                    <span className="absolute left-6 top-1/2 -translate-y-1/2 font-black text-gray-400 text-2xl">Rp</span>
                    <input 
                      type="number" 
                      placeholder="0" 
                      className="w-full p-6 pl-16 bg-gray-50 border-2 border-gray-100 rounded-[2rem] font-black text-4xl text-right text-black focus:border-pink-500 focus:bg-white focus:outline-none transition-all"
                      value={amountPaid}
                      onChange={(e) => setAmountPaid(e.target.value)}
                      autoFocus
                    />
                  </div>
                  <div className="grid grid-cols-3 gap-2">
                    {quickDenominations.map(d => (
                      <button key={d} onClick={() => setAmountPaid(d.toString())} className="py-3 bg-gray-50 rounded-xl text-[10px] font-black text-black hover:bg-pink-50 hover:text-pink-600 transition-all">+{d/1000}rb</button>
                    ))}
                  </div>
                </div>
              )}

              {paymentMethod === PaymentMethod.QRIS && (
                <div className="flex flex-col items-center gap-4 py-4 animate-in zoom-in-95">
                  <div className="bg-white p-4 rounded-3xl shadow-lg border-2 border-pink-50">
                    <img src={`https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=WHY-SEMBAKO-${generateId()}`} alt="QRIS" className="w-44 h-44" />
                  </div>
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">Silahkan Scan QRIS Diatas</p>
                </div>
              )}

              {paymentMethod === PaymentMethod.TRANSFER && (
                <div className="space-y-4 animate-in slide-in-from-top-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <p className="text-[9px] font-bold text-pink-600 uppercase tracking-widest">Pilih Bank</p>
                      <div className="grid grid-cols-2 gap-2">
                        {bankOptions.map(bank => (
                          <button key={bank} onClick={() => setPaymentProvider(bank)} className={`p-3 rounded-xl text-[10px] font-black border transition-all ${paymentProvider === bank ? 'bg-pink-50 border-pink-500 text-pink-700' : 'bg-white border-gray-100 text-gray-500'}`}>{bank}</button>
                        ))}
                      </div>
                    </div>
                    <div className="space-y-2">
                      <p className="text-[9px] font-bold text-pink-600 uppercase tracking-widest">E-Wallet</p>
                      <div className="grid grid-cols-2 gap-2">
                        {ewalletOptions.map(ew => (
                          <button key={ew} onClick={() => setPaymentProvider(ew)} className={`p-3 rounded-xl text-[10px] font-black border transition-all ${paymentProvider === ew ? 'bg-pink-50 border-pink-500 text-pink-700' : 'bg-white border-gray-100 text-gray-500'}`}>{ew}</button>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              )}

              <button 
                onClick={handleCheckout} 
                disabled={(paymentMethod === PaymentMethod.CASH && (!amountPaid || Number(amountPaid) < cartTotal)) || (paymentMethod === PaymentMethod.TRANSFER && !paymentProvider)}
                className="w-full py-6 bg-pink-600 text-white rounded-[2rem] font-black text-2xl shadow-2xl shadow-pink-100 hover:bg-pink-700 transition-all active:scale-95 disabled:opacity-50"
              >
                KONFIRMASI PEMBAYARAN
              </button>
            </div>
          </div>
        </div>
      )}

      {lastTransaction && (
        <div className="fixed inset-0 bg-white z-[200] flex flex-col items-center justify-center p-8 text-center animate-in fade-in zoom-in-110">
          <div className="no-print flex flex-col items-center">
            <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6 animate-bounce">
              <CheckCircle2 size={48} />
            </div>
            <h2 className="text-4xl font-black text-gray-800 mb-2">Transaksi Berhasil!</h2>
            <div className="bg-gray-50 px-8 py-4 rounded-2xl mb-8">
              <p className="text-gray-400 font-bold uppercase tracking-widest text-[10px]">Kembalian</p>
              <p className="text-3xl font-black text-green-600">{formatCurrency(lastTransaction.change)}</p>
            </div>
            <div className="flex gap-4 w-full max-w-md">
              <button onClick={handlePrint} className="flex-1 py-5 border-4 border-pink-600 text-pink-600 rounded-[2rem] font-black text-lg hover:bg-pink-50 flex items-center justify-center gap-3">
                <Printer size={24} /> Cetak Struk
              </button>
              <button onClick={() => setLastTransaction(null)} className="flex-1 py-5 bg-pink-600 text-white rounded-[2rem] font-black text-lg shadow-xl hover:bg-pink-700 transition-all">
                Selesai
              </button>
            </div>
          </div>
          <div className="print-only mt-8">
            <Receipt transaction={lastTransaction} />
          </div>
        </div>
      )}

      <style>{`
        @keyframes scan {
          0% { transform: translateY(0); }
          50% { transform: translateY(184px); }
          100% { transform: translateY(0); }
        }
        @media print {
          body * { visibility: hidden; }
          .print-only, .print-only * { visibility: visible; }
          .print-only { position: absolute; left: 0; top: 0; width: 100%; }
        }
      `}</style>
    </div>
  );
};

export default Cashier;

import React, { useState, useMemo } from 'react';
import { PackagePlus, Edit2, ArrowUpDown, Filter, Trash2, Search, Plus, Check, ChevronDown, SortAsc, SortDesc, X, AlertTriangle, ImageIcon, ScanLine } from 'lucide-react';
import { Product, UnitType } from '../types';
import { formatCurrency, generateId } from '../utils';

interface InventoryProps {
  products: Product[];
  onAddStock: (id: string, amount: number) => void;
  onUpdateProduct: (product: Product) => void;
  onAddProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
}

type SortOrder = 'asc' | 'desc' | 'none';

const Inventory: React.FC<InventoryProps> = ({ products, onAddStock, onUpdateProduct, onAddProduct, onDeleteProduct }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [quickEditingStockId, setQuickEditingStockId] = useState<string | null>(null);
  const [stockAmount, setStockAmount] = useState<string>('');
  const [selectedCategory, setSelectedCategory] = useState<string>('Semua');
  const [sortOrder, setSortOrder] = useState<SortOrder>('none');
  const [showCategoryMenu, setShowCategoryMenu] = useState(false);
  const [showFormModal, setShowFormModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentProductId, setCurrentProductId] = useState<string | null>(null);
  const [productToDelete, setProductToDelete] = useState<{id: string, name: string} | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    barcode: '',
    price: '',
    category: '',
    stock: '',
    minStock: '',
    unit: UnitType.PCS,
    imageUrl: ''
  });

  const categories = useMemo(() => {
    const cats = Array.from(new Set(products.map(p => p.category)));
    return ['Semua', ...cats];
  }, [products]);

  const processedProducts = useMemo(() => {
    let result = products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm));
      const matchesCategory = selectedCategory === 'Semua' || p.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });

    if (sortOrder === 'asc') {
      result.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sortOrder === 'desc') {
      result.sort((a, b) => b.name.localeCompare(a.name));
    }

    return result;
  }, [products, searchTerm, selectedCategory, sortOrder]);

  const handleQuickStockUpdate = (id: string) => {
    const amt = Number(stockAmount);
    if (!isNaN(amt) && amt !== 0) {
      onAddStock(id, amt);
      setQuickEditingStockId(null);
      setStockAmount('');
    }
  };

  const openAddModal = () => {
    setIsEditing(false);
    setCurrentProductId(null);
    setFormData({
      name: '',
      barcode: '',
      price: '',
      category: '',
      stock: '',
      minStock: '',
      unit: UnitType.PCS,
      imageUrl: ''
    });
    setShowFormModal(true);
  };

  const openEditModal = (product: Product) => {
    setIsEditing(true);
    setCurrentProductId(product.id);
    setFormData({
      name: product.name,
      barcode: product.barcode || '',
      price: product.price.toString(),
      category: product.category,
      stock: product.stock.toString(),
      minStock: product.minStock.toString(),
      unit: product.unit,
      imageUrl: product.imageUrl || ''
    });
    setShowFormModal(true);
  };

  const confirmDelete = () => {
    if (productToDelete) {
      onDeleteProduct(productToDelete.id);
      setProductToDelete(null);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.price || !formData.category) {
      alert("Mohon lengkapi data produk!");
      return;
    }

    const productData: Product = {
      id: isEditing && currentProductId ? currentProductId : generateId(),
      barcode: formData.barcode,
      name: formData.name,
      price: Number(formData.price),
      category: formData.category,
      stock: Number(formData.stock) || 0,
      minStock: Number(formData.minStock) || 0,
      unit: formData.unit as UnitType,
      imageUrl: formData.imageUrl
    };

    if (isEditing) {
      onUpdateProduct(productData);
    } else {
      onAddProduct(productData);
    }

    setShowFormModal(false);
  };

  const toggleSort = () => {
    setSortOrder(prev => {
      if (prev === 'none') return 'asc';
      if (prev === 'asc') return 'desc';
      return 'none';
    });
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-800">Manajemen Stok</h2>
          <p className="text-gray-500 font-medium">Kelola inventori dan ketersediaan barang.</p>
        </div>
        <div className="flex gap-2">
           <button 
             onClick={openAddModal}
             className="flex items-center gap-2 px-6 py-3 bg-pink-600 text-white rounded-2xl font-black shadow-lg shadow-pink-100 hover:bg-pink-700 transition-all active:scale-95"
           >
             <PackagePlus size={20} />
             Tambah Produk Baru
           </button>
        </div>
      </header>

      <div className="bg-white rounded-[2rem] border border-gray-100 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex flex-col md:flex-row gap-4 items-center justify-between bg-gray-50/30">
          <div className="relative w-full md:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Cari nama atau barcode..."
              className="w-full pl-11 pr-4 py-3 bg-white border border-transparent rounded-xl shadow-sm focus:ring-2 focus:ring-pink-100 focus:outline-none transition-all text-gray-900 font-medium"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex gap-2 relative w-full md:w-auto">
            <button 
              onClick={() => setShowCategoryMenu(!showCategoryMenu)}
              className={`flex-1 md:flex-none flex items-center justify-between gap-3 px-5 py-3 rounded-xl transition-all border ${
                selectedCategory !== 'Semua' 
                  ? 'bg-pink-600 border-pink-600 text-white font-bold' 
                  : 'bg-white border-gray-100 text-gray-500 hover:border-pink-200'
              }`}
            >
              <div className="flex items-center gap-2">
                <Filter size={18} />
                <span className="text-sm uppercase tracking-wider">{selectedCategory}</span>
              </div>
              <ChevronDown size={14} className={`transition-transform duration-200 ${showCategoryMenu ? 'rotate-180' : ''}`} />
            </button>

            {showCategoryMenu && (
              <>
                <div className="fixed inset-0 z-10" onClick={() => setShowCategoryMenu(false)}></div>
                <div className="absolute right-0 mt-14 w-56 bg-white border border-gray-100 rounded-2xl shadow-2xl z-20 py-2 animate-in fade-in zoom-in-95 duration-200">
                  <p className="px-4 py-2 text-[10px] font-black text-gray-400 uppercase tracking-widest border-b border-gray-50 mb-1">Pilih Kategori</p>
                  {categories.map(cat => (
                    <button
                      key={cat}
                      onClick={() => {
                        setSelectedCategory(cat);
                        setShowCategoryMenu(false);
                      }}
                      className="w-full flex items-center justify-between px-4 py-3 text-sm font-bold text-gray-700 hover:bg-pink-50 hover:text-pink-600 transition-colors"
                    >
                      {cat}
                      {selectedCategory === cat && <Check size={16} />}
                    </button>
                  ))}
                </div>
              </>
            )}

            <button 
              onClick={toggleSort}
              className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-5 py-3 rounded-xl transition-all border bg-white border-gray-100 text-gray-500 hover:border-pink-200 font-bold`}
            >
              {sortOrder === 'desc' ? <SortDesc size={18} /> : (sortOrder === 'asc' ? <SortAsc size={18} /> : <ArrowUpDown size={18} />)}
              <span className="text-sm uppercase tracking-wider">Sort</span>
            </button>
          </div>
        </div>

        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white text-gray-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <th className="px-8 py-5 border-b border-gray-100">Info Produk</th>
                <th className="px-8 py-5 border-b border-gray-100">Barcode</th>
                <th className="px-8 py-5 border-b border-gray-100">Harga Jual</th>
                <th className="px-8 py-5 border-b border-gray-100">Stok</th>
                <th className="px-8 py-5 border-b border-gray-100">Status</th>
                <th className="px-8 py-5 border-b border-gray-100 text-center">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {processedProducts.length > 0 ? (
                processedProducts.map(product => (
                  <tr key={product.id} className="hover:bg-pink-50/20 transition-colors group animate-in slide-in-from-left-2 duration-300">
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-14 h-14 bg-gray-50 rounded-2xl border border-gray-100 overflow-hidden shadow-sm flex-shrink-0">
                          {product.imageUrl ? (
                            <img src={product.imageUrl} className="w-full h-full object-cover" />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center text-gray-300">
                              <ImageIcon size={24} />
                            </div>
                          )}
                        </div>
                        <div>
                          <span className="font-black text-gray-800 block leading-tight">{product.name}</span>
                          <span className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">{product.category}</span>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                       <div className="flex items-center gap-2 text-gray-500">
                          <ScanLine size={14} className="text-pink-500" />
                          <span className="font-mono text-xs font-bold">{product.barcode || '-'}</span>
                       </div>
                    </td>
                    <td className="px-8 py-6">
                      <span className="font-black text-gray-900">{formatCurrency(product.price)}</span>
                    </td>
                    <td className="px-8 py-6">
                      {quickEditingStockId === product.id ? (
                        <div className="flex items-center gap-2">
                          <input 
                             type="number"
                             className="w-20 p-2 border-2 border-pink-100 rounded-xl focus:outline-none focus:border-pink-500 text-gray-900 font-black text-center"
                             placeholder="+/-"
                             value={stockAmount}
                             onChange={(e) => setStockAmount(e.target.value)}
                             autoFocus
                          />
                          <button 
                            onClick={() => handleQuickStockUpdate(product.id)}
                            className="w-9 h-9 flex items-center justify-center bg-pink-600 text-white rounded-xl hover:bg-pink-700 transition-colors shadow-lg shadow-pink-100"
                          >
                            <Check size={18} />
                          </button>
                        </div>
                      ) : (
                        <div className="flex items-center gap-2">
                          <span className={`font-black text-lg ${product.stock <= product.minStock ? 'text-red-600' : 'text-black'}`}>
                            {product.stock}
                          </span>
                          <span className="text-[10px] font-bold text-gray-400 uppercase">{product.unit}</span>
                          <button 
                             onClick={() => setQuickEditingStockId(product.id)}
                             className="opacity-0 group-hover:opacity-100 w-8 h-8 flex items-center justify-center text-pink-500 bg-pink-50 rounded-lg transition-all active:scale-90"
                             title="Update Stok"
                          >
                            <Plus size={16} />
                          </button>
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-6">
                      {product.stock <= product.minStock ? (
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-red-50 text-red-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-red-100 w-fit">
                          <AlertTriangle size={12} />
                          Low Stock
                        </div>
                      ) : (
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-green-50 text-green-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-green-100 w-fit">
                          <Check size={12} />
                          Aman
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center justify-center gap-3">
                        <button 
                          onClick={() => openEditModal(product)}
                          className="w-10 h-10 flex items-center justify-center text-gray-400 hover:text-pink-600 hover:bg-pink-50 rounded-xl transition-all active:scale-90 border border-transparent hover:border-pink-100"
                        >
                          <Edit2 size={18} />
                        </button>
                        <button 
                          onClick={() => setProductToDelete({id: product.id, name: product.name})}
                          className="w-10 h-10 flex items-center justify-center text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all active:scale-90 border border-transparent hover:border-pink-100"
                        >
                          <Trash2 size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={6} className="px-8 py-32 text-center">
                    <div className="flex flex-col items-center justify-center text-gray-300">
                      <Search size={64} className="mb-4 opacity-10" />
                      <p className="font-bold text-lg">Produk tidak ditemukan</p>
                    </div>
                  </td>
                </tr>
